// 9-B. 사용자 카페 건의 & 한줄 후기 로컬 저장소 헬퍼
const USER_SUGGESTED_CAFES_KEY = "khu_kagong_user_suggested_cafes_v1";
const USER_PLACE_REVIEWS_KEY = "khu_kagong_place_reviews_v1";

function getUserSuggestedCafes() {
  try {
    const raw = localStorage.getItem(USER_SUGGESTED_CAFES_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (_e) {
    return [];
  }
}

function saveUserSuggestedCafe(newCafe) {
  const list = getUserSuggestedCafes();
  list.push(newCafe);
  try {
    localStorage.setItem(USER_SUGGESTED_CAFES_KEY, JSON.stringify(list));
  } catch (_e) {}
}

function getStoredReviewsMap() {
  try {
    const raw = localStorage.getItem(USER_PLACE_REVIEWS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (_e) {
    return {};
  }
}

function getPlaceReviews(place) {
  const map = getStoredReviewsMap();
  const userList = Array.isArray(map[String(place.id)]) ? map[String(place.id)] : [];

  const seedReviews = [];
  if (place.outlets) {
    seedReviews.push({
      tag: place.tags && place.tags.includes("콘센트많음") ? "콘센트 넉넉" : "자리 팁",
      text: `${place.outlets} — 노트북 작업할 때 참고하면 좋아요.`,
      author: "경희대 카공러",
      date: "인증 후기",
    });
  }
  if (place.summary) {
    seedReviews.push({
      tag:
        place.tags && place.tags.includes("조용한")
          ? "조용해요"
          : place.tags && place.tags.includes("야간")
          ? "밤공부 최고"
          : "카공 추천",
      text: place.note ? `${place.summary} (${place.note})` : place.summary,
      author: "캠퍼스 카공 요정",
      date: "기본 가이드",
    });
  }
  return [...userList, ...seedReviews];
}

function savePlaceReview(placeId, tag, text) {
  const map = getStoredReviewsMap();
  const key = String(placeId);
  const prev = Array.isArray(map[key]) ? map[key] : [];
  const now = new Date();
  const dateLabel = `${now.getMonth() + 1}.${now.getDate()} 방금`;
  const item = {
    tag: tag || "콘센트 넉넉",
    text: text.trim(),
    author: "익명 경희인",
    date: dateLabel,
  };
  map[key] = [item, ...prev];
  try {
    localStorage.setItem(USER_PLACE_REVIEWS_KEY, JSON.stringify(map));
  } catch (_e) {}
  return item;
}

function escapeHtmlSafe(str) {
  return String(str || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// 10. URL 파라미터 동기화 (?campus=seoul|global&anchor=...&mood=...)
function syncStateFromURL() {
  const params = new URLSearchParams(window.location.search);
  const campusParam = params.get("campus");
  const anchorParam = params.get("anchor");
  const moodParam = params.get("mood");
  const radiusParam = params.get("radius");
  const promptParam = params.get("q") || params.get("prompt");

  if (campusParam === "seoul" || campusParam === "global") {
    state.campus = campusParam;
  }

  const anchors = CAMPUS_ANCHORS[state.campus];
  if (anchorParam === "gps") {
    state.anchorKey = "gps";
  } else {
    const legacyGlobalMap = {
      main_gate: "junggeon",
      yeongtong_stn: "jungsang",
      sasaek_sq: "maeul",
    };
    const normalizedAnchorParam =
      state.campus === "global" && legacyGlobalMap[anchorParam]
        ? legacyGlobalMap[anchorParam]
        : anchorParam;
    const matchedAnchor =
      anchors.find((a) => a.key === normalizedAnchorParam) || anchors[0];
    state.anchorKey = matchedAnchor.key;
    state.anchorCoord = {
      lat: matchedAnchor.lat,
      lng: matchedAnchor.lng,
      label: matchedAnchor.label,
    };
  }

  if (moodParam && MOOD_CARDS.some((m) => m.id === moodParam)) {
    state.selectedMood = moodParam;
    state.activeFilterTab = "mood";
  }

  if (radiusParam !== null && ["300", "500", "1000", "0"].includes(radiusParam)) {
    state.radiusMeters = Number(radiusParam);
  }

  if (promptParam && promptParam.trim()) {
    state.aiPromptQuery = promptParam.trim();
  }
}

function updateURLParams() {
  const url = new URL(window.location.href);
  url.searchParams.set("campus", state.campus);
  url.searchParams.set("anchor", state.anchorKey);
  if (state.selectedMood) {
    url.searchParams.set("mood", state.selectedMood);
  } else {
    url.searchParams.delete("mood");
  }
  if (state.aiPromptQuery) {
    url.searchParams.set("q", state.aiPromptQuery);
  } else {
    url.searchParams.delete("q");
    url.searchParams.delete("prompt");
  }
  window.history.replaceState({}, "", url.toString());
}

function getCanonicalShareUrl(placeId = null) {
  const shareUrl = new URL(CANONICAL_SERVICE_URL);
  shareUrl.searchParams.set("campus", state.campus);
  shareUrl.searchParams.set("anchor", state.anchorKey);
  if (state.selectedMood) {
    shareUrl.searchParams.set("mood", state.selectedMood);
  }
  if (state.aiPromptQuery) {
    shareUrl.searchParams.set("q", state.aiPromptQuery);
  }
  if (placeId) {
    shareUrl.searchParams.set("place", String(placeId));
  }
  return shareUrl.toString();
}

// 11. 필터링 및 거리·영업상태 계산 파이프라인
function getBaseFilteredPlaces(refDate) {
  const activePlaces = window.HoursEngine.filterActivePlaces(state.places);

  return activePlaces
    .filter((p) => p.campus === state.campus)
    .map((p) => {
      const distance = getDistanceMeters(
        state.anchorCoord.lat,
        state.anchorCoord.lng,
        p.lat,
        p.lng
      );
      const businessStatus = window.HoursEngine.getPlaceBusinessStatus(
        p,
        refDate
      );
      return {
        ...p,
        distance,
        businessStatus,
      };
    })
    .filter((p) => {
      // 반경 필터
      if (state.radiusMeters > 0 && p.distance > state.radiusMeters) {
        return false;
      }
      // 영업 중만 토글
      if (state.openNowOnly && !p.businessStatus.isOpen) {
        return false;
      }
      return true;
    });
}

function applyMoodAndDetails(places, moodId, detailsSet, refDate) {
  const moodObj = moodId ? MOOD_CARDS.find((m) => m.id === moodId) : null;
  const activeConds = DETAIL_CONDITIONS.filter((c) => detailsSet.has(c.key));

  return places.filter((p) => {
    if (moodObj && !moodObj.match(p, refDate)) {
      return false;
    }
    for (let i = 0; i < activeConds.length; i++) {
      if (!activeConds[i].match(p, refDate)) {
        return false;
      }
    }
    return true;
  });
}

function getSortedDisplayPlaces(refDate) {
  const base = getBaseFilteredPlaces(refDate);
  let filtered = applyMoodAndDetails(
    base,
    state.selectedMood,
    state.selectedDetails,
    refDate
  );

  // 프롬프트 추천 모드가 활성화된 경우 프롬프트 매칭 점수로 추가 정렬/필터
  if (state.aiPromptQuery && state.aiPromptQuery.trim()) {
    const scored = scorePlacesByAiPrompt(filtered, state.aiPromptQuery, refDate);
    if (scored.matchedPlaces.length > 0) {
      return scored.matchedPlaces;
    }
  }

  // 5-3절: 기본 정렬은 영업 중 우선 → 거리순
  return filtered.sort((a, b) => {
    if (a.businessStatus.isOpen !== b.businessStatus.isOpen) {
      return a.businessStatus.isOpen ? -1 : 1;
    }
    return a.distance - b.distance;
  });
}

// 11-2. ✨ AI 프롬프트 카페 추천 엔진 (자연어 문장 분석 + URL ?q=... 프롬프트 링크 공유 지원)
function parseAiPromptIntent(rawPrompt) {
  const q = String(rawPrompt || "").trim().toLowerCase();
  const intent = {
    raw: String(rawPrompt || "").trim(),
    campus: null,
    anchorKey: null,
    radiusMeters: null,
    visitTimeMode: null,
    tags: [],
    keywords: [],
    reasons: [],
  };
  if (!q) return intent;

  // 1) 캠퍼스 & 기준점 감지
  if (/국제캠|국캠|중건|정문\s*건너편|중상|중심\s*상가|마을|정문쪽\s*동네|작은\s*동네|수원|영통|서천|사색|우정원|제2긱|2긱|전정대|예디대|멀관|멀티미디어|외국어대학|외대\s*컴포즈|전자국제|달콤한\s*위로/.test(q)) {
    intent.campus = "global";
    intent.reasons.push("국제캠퍼스");
  } else if (/서울캠|설캠|회기|한국외대|외대앞|이문|청량|호관대|호텔관광|늘품|청운관|다향|오비스홀|매그놀리아|법학관|법향|푸른솔|의학관/.test(q)) {
    intent.campus = "seoul";
    intent.reasons.push("서울캠퍼스");
  }

  if (/내\s*위치|내\s*주변|현\s*위치|가까운/.test(q)) {
    intent.anchorKey = "gps";
  } else if (/중건|정문\s*건너편/.test(q)) {
    intent.anchorKey = "junggeon";
    intent.campus = "global";
    intent.reasons.push("중건(정문건너편)");
  } else if (/중상|중심\s*상가|영통역|영통/.test(q)) {
    intent.anchorKey = "jungsang";
    intent.campus = "global";
    intent.reasons.push("중상(영통역 중심상가)");
  } else if (/마을|작은\s*동네|정문쪽\s*동네|서천|사색의?\s*광장|사색/.test(q)) {
    intent.anchorKey = "maeul";
    intent.campus = "global";
    intent.reasons.push("마을(정문쪽 작은 동네)");
  } else if (/후문/.test(q)) {
    intent.anchorKey = "back_gate";
    intent.campus = "seoul";
    intent.reasons.push("후문 인근");
  } else if (/회기역|회기/.test(q)) {
    intent.anchorKey = "hoegi_stn";
    intent.campus = "seoul";
    intent.reasons.push("회기역 인근");
  } else if (/정문/.test(q)) {
    if (intent.campus === "global" || state.campus === "global") {
      intent.anchorKey = "junggeon";
      intent.reasons.push("중건(정문건너편)");
    } else {
      intent.anchorKey = "main_gate";
      intent.reasons.push("정문 인근");
    }
  }

  // 2) 거리/반경 감지
  if (/가까운|근처|코앞|공강|300m|5분/.test(q)) {
    intent.radiusMeters = 500;
  }

  // 3) 시간대 감지
  if (/24시간|밤샘|새벽|올나잇|벼락치기/.test(q)) {
    intent.tags.push("24시간");
    intent.reasons.push("24시간·새벽 카공");
  } else if (/밤\s*늦게|야간|저녁|밤\s*10시|밤\s*11시|늦게까지/.test(q)) {
    intent.tags.push("밤늦게까지");
    intent.reasons.push("밤늦게까지 영업");
  } else if (/아침|오전|일찍|모닝|9시/.test(q)) {
    intent.visitTimeMode = "morning09";
    intent.reasons.push("아침 일찍 오픈");
  }

  // 4) 좌석·분위기·특징 감지
  if (/콘센트|충전|배터리|노트북|전원|멀티탭/.test(q)) {
    intent.tags.push("콘센트많음");
    intent.reasons.push("콘센트 넉넉함");
  }
  if (/조용|집중|빡공|독서실|시험/.test(q)) {
    intent.tags.push("조용한");
    intent.reasons.push("조용히 집중하기 좋음");
  }
  if (/혼자|1인석|혼공|바테이블|창가/.test(q)) {
    intent.tags.push("1인석");
    intent.reasons.push("1인석 완비");
  }
  if (/팀플|회의|단체|여러\s*명|같이|과제/.test(q)) {
    intent.tags.push("단체석");
    intent.reasons.push("팀플·단체석");
  }
  if (/예쁜|감성|분위기|인스타|디저트|맛집|케이크|베이글|크루아상|로스터리/.test(q)) {
    intent.tags.push("분위기좋음");
    intent.reasons.push("분위기·디저트 맛집");
  }
  if (/수다|대화|얘기|떠들/.test(q)) {
    intent.tags.push("대화가능");
    intent.reasons.push("대화하며 공부 가능");
  }
  if (/싼|저렴|가성비|저가|부담\s*없|메가|컴포즈|빽다방|고씨/.test(q)) {
    intent.tags.push("저가");
    intent.reasons.push("가성비 최고");
  }
  if (/교내|학교\s*안|캠퍼스\s*안|도서관|중도|청운|네오|호관대|호텔관광|늘품|다향|오비스|매그놀리아|법학관|법향|푸른솔|의학관|우정원|제2긱|2긱|전정대|외대\s*컴포즈|외국어대학|예디대|예술디자인|멀관|멀티미디어|학생회관|공학관|쿠피|생협/.test(q)) {
    intent.tags.push("교내카페");
    intent.reasons.push("교내 카페");
  }

  // 5) 프롬프트 문장에 대응하는 '오늘의 카공 카드(mood)' & '세부 조건(detail)' 자동 매칭
  intent.matchedDetails = intent.tags.filter((t) =>
    ["콘센트많음", "조용한", "1인석", "교내카페", "24시간"].includes(t)
  );

  if (/24시간|밤샘|새벽|올나잇|벼락치기|내일\s*시험/.test(q)) {
    intent.matchedMood = "cram";
  } else if (/밤\s*늦게|야간|저녁|밤\s*10시|밤\s*11시|늦게까지/.test(q)) {
    intent.matchedMood = "late_night";
  } else if (/팀플|회의|단체|여러\s*명|같이|과제/.test(q)) {
    intent.matchedMood = "team";
  } else if (/싼|저렴|가성비|저가|부담\s*없|메가|컴포즈|빽다방|고씨/.test(q)) {
    intent.matchedMood = "budget";
  } else if (/예쁜|감성|분위기|인스타|디저트|맛집|케이크|베이글|크루아상|로스터리|수다|대화|얘기|떠들/.test(q)) {
    intent.matchedMood = "chatty_pretty";
  } else if (/공강|1시간|멀리|귀찮|코앞/.test(q)) {
    intent.matchedMood = "gap_hour";
  } else if (/배터리|간당간당|충전|콘센트|노트북|전원|멀티탭/.test(q) && !/조용|혼자|1인석/.test(q)) {
    intent.matchedMood = "battery";
  } else if (/조용|집중|빡공|독서실|혼자|1인석|혼공|시험/.test(q)) {
    intent.matchedMood = "alone";
  } else {
    intent.matchedMood = null;
  }

  // 6) 개별 단어 키워드 추출 (가게 이름, 메뉴, 요약문 매칭용)
  const stopWords = new Set([
    "카페", "추천", "추천해줘", "추천해", "알려줘", "찾아줘", "어디", "있어", "좋은", "하기", "공부", "카공", "할만한", "곳", "좀", "근처", "주변", "에서", "하고", "싶어", "갈만한",
    "정문", "후문", "회기", "회기역", "영통", "영통역", "사색", "광장", "서울캠", "국제캠", "조용한", "조용하고", "콘센트", "많은"
  ]);
  q.split(/[\s,·!?~]+/)
    .map((w) => w.replace(/(에서|으로|이랑|하고|할래|해줘|추천|카페|근처|주변)$/g, "").trim())
    .filter((w) => w.length >= 2 && !stopWords.has(w))
    .forEach((w) => intent.keywords.push(w));

  return intent;
}

function scorePlacesByAiPrompt(places, rawPrompt, refDate) {
  const intent = parseAiPromptIntent(rawPrompt);
  const scoredList = places.map((p) => {
    let score = 0;
    const matchedReasons = [];

    // 영업 중 가산점 (현재 열려 있는 곳 우선 추천)
    if (p.businessStatus && p.businessStatus.isOpen) {
      score += 28;
    }

    // 태그 일치 점수
    intent.tags.forEach((t) => {
      if (t === "24시간" && window.HoursEngine.is24HoursPlace(p)) {
        score += 35;
        matchedReasons.push("24시간");
      } else if (t === "밤늦게까지" && window.HoursEngine.isLateNightByHours(p, refDate)) {
        score += 30;
        matchedReasons.push("심야영업");
      } else if (p.tags.includes(t)) {
        score += 28;
        matchedReasons.push(TAG_DISPLAY_LABELS[t] || t);
      }
    });

    // 거리 가산점 (가까울수록 높은 점수)
    if (typeof p.distance === "number") {
      if (p.distance <= 250) score += 18;
      else if (p.distance <= 500) score += 10;
      else if (p.distance <= 800) score += 4;
    }

    // 텍스트 키워드 매칭 (매장 이름, 한줄 요약, 콘센트 설명, 노트)
    const haystack = `${p.name} ${p.summary} ${p.outlets} ${p.note || ""} ${p.tags.join(" ")}`.toLowerCase();
    intent.keywords.forEach((kw) => {
      if (p.name.toLowerCase().includes(kw)) {
        score += 45;
      } else if (haystack.includes(kw)) {
        score += 20;
      }
    });

    return {
      place: p,
      score,
      matchedReasons: Array.from(new Set(matchedReasons)),
    };
  });

  scoredList.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (a.place.businessStatus.isOpen !== b.place.businessStatus.isOpen) {
      return a.place.businessStatus.isOpen ? -1 : 1;
    }
    return a.place.distance - b.place.distance;
  });

  const hasSpecificFilter = intent.tags.length > 0 || intent.keywords.length > 0;
  const matched = hasSpecificFilter
    ? scoredList.filter((item) => item.score >= 20)
    : scoredList;

  const finalItems = matched.length > 0 ? matched : scoredList;
  return {
    intent,
    topPicks: finalItems.slice(0, 3),
    matchedPlaces: finalItems.map((item) => item.place),
  };
}

function applyAiPromptRecommendation(rawPrompt, fromUrl = false) {
  const cleanPrompt = String(rawPrompt || "").trim();
  const inputEl = document.getElementById("aiPromptInput");
  const clearBtn = document.getElementById("btnClearAiPrompt");
  if (inputEl && inputEl.value !== cleanPrompt) {
    inputEl.value = cleanPrompt;
  }
  if (clearBtn) {
    clearBtn.classList.toggle("hidden", !cleanPrompt);
  }

  if (!cleanPrompt) {
    state.aiPromptQuery = "";
    state.aiPromptResult = null;
    const box = document.getElementById("aiPromptResultBox");
    if (box) box.classList.add("hidden");
    renderAll(false);
    return;
  }

  state.aiPromptQuery = cleanPrompt;
  const intent = parseAiPromptIntent(cleanPrompt);

  // 프롬프트에 캠퍼스나 기준점이 명시된 경우 자동 전환
  let shouldRecenter = false;
  if (intent.campus && intent.campus !== state.campus) {
    state.campus = intent.campus;
    const defaultAnchor = CAMPUS_ANCHORS[state.campus][0];
    state.anchorKey = defaultAnchor.key;
    state.anchorCoord = {
      lat: defaultAnchor.lat,
      lng: defaultAnchor.lng,
      label: defaultAnchor.label,
    };
    shouldRecenter = true;
  }

  if (intent.anchorKey && intent.anchorKey !== "gps") {
    const foundAnchor = CAMPUS_ANCHORS[state.campus].find(
      (a) => a.key === intent.anchorKey
    );
    if (foundAnchor) {
      state.anchorKey = foundAnchor.key;
      state.anchorCoord = {
        lat: foundAnchor.lat,
        lng: foundAnchor.lng,
        label: foundAnchor.label,
      };
      shouldRecenter = true;
    }
  } else if (intent.anchorKey === "gps" && state.userGpsCoord) {
    state.anchorKey = "gps";
    state.anchorCoord = { ...state.userGpsCoord };
    shouldRecenter = true;
  }

  if (intent.visitTimeMode) {
    state.visitTimeMode = intent.visitTimeMode;
  }

  // 전체 반경에서 최적 추천
  state.radiusMeters = 0;

  // ★ 프롬프트 검색 시 문장에 맞는 '오늘의 카공 카드'와 '세부 조건 칩'도 자동으로 함께 선택!
  const refDate = getEffectiveReferenceDate();
  const baseForMatch = getBaseFilteredPlaces(refDate);
  if (intent.matchedDetails && intent.matchedDetails.length > 0) {
    const autoDetails = new Set();
    intent.matchedDetails.forEach((dKey) => {
      const testSet = new Set(autoDetails);
      testSet.add(dKey);
      if (applyMoodAndDetails(baseForMatch, null, testSet, refDate).length > 0) {
        autoDetails.add(dKey);
      }
    });
    if (autoDetails.size > 0) {
      state.selectedDetails = autoDetails;
    }
  }
  if (intent.matchedMood) {
    if (
      applyMoodAndDetails(
        baseForMatch,
        intent.matchedMood,
        state.selectedDetails,
        refDate
      ).length > 0
    ) {
      state.selectedMood = intent.matchedMood;
    }
  }

  const detailModal = document.getElementById("detailFilterModal");
  if (detailModal) {
    detailModal.classList.add("hidden");
  }

  closePlaceDetail();
  const listViewEl = document.getElementById("sheetListView");
  if (listViewEl) {
    listViewEl.classList.remove("hidden");
  }

  renderAll(shouldRecenter || !fromUrl);
  setMainViewMode("list", "ai_prompt_recommend", false);

  const scrollBody = document.getElementById("sheetScrollBody");
  if (scrollBody) {
    scrollBody.scrollTop = 0;
  }

  const greetingImg = document.getElementById("greetingFairyImg");
  if (greetingImg) triggerFairySparkleAndHop(greetingImg);
  if (!fromUrl) {
    showToast("🧚 질문에 맞는 카공 카드·조건을 자동 선택해 TOP 추천을 띄웠어요!");
  }
}

const GEMINI_KEY_STORAGE = "khu_gemini_api_key_v1";
const geminiReplyCache = new Map();

function getStoredGeminiApiKey() {
  try {
    const saved = localStorage.getItem(GEMINI_KEY_STORAGE);
    if (saved && saved.trim()) return saved.trim();
  } catch (_e) {}
  if (typeof window !== "undefined" && window.KHU_GEMINI_API_KEY) {
    return String(window.KHU_GEMINI_API_KEY).trim();
  }
  return "";
}

function syncGeminiKeyUiState() {
  const hasKey = Boolean(getStoredGeminiApiKey());
  const dot = document.getElementById("geminiKeyStatusDot");
  const btnText = document.getElementById("geminiKeyBtnText");
  const menuLabel = document.getElementById("menuGeminiKeyLabel");
  const inputEl = document.getElementById("geminiApiKeyInput");

  if (dot) dot.classList.toggle("is-connected", hasKey);
  if (btnText) btnText.textContent = hasKey ? "Gemini ON" : "Gemini API";
  if (menuLabel) {
    menuLabel.textContent = hasKey ? "Gemini API 연동됨 ✓" : "Gemini API 키 연동";
  }
  if (inputEl && hasKey && !inputEl.value) {
    inputEl.value = getStoredGeminiApiKey();
  }
}

function buildConversationalFairyReply(effectiveQuery, intent, topPicks) {
  if (!topPicks || topPicks.length === 0) {
    return "아쉽게도 지금 조건에 딱 맞는 카페를 찾지 못했어요. 반경을 넓히거나 다른 키워드로 제발요에게 다시 물어봐 주세요!";
  }

  const top1 = topPicks[0].place;
  const top2 = topPicks[1] ? topPicks[1].place : null;
  const top3 = topPicks[2] ? topPicks[2].place : null;

  const dist1 = formatDistanceLabel(top1.distance);
  const status1 = top1.businessStatus?.label || top1.hours || "영업시간 확인";
  const reasonPrefix =
    intent.reasons && intent.reasons.length > 0
      ? `${intent.reasons.join(" · ")} 조건으로 찾아봤어요! `
      : `"${effectiveQuery}" 조건으로 찾아봤어요! `;

  let reply = `${reasonPrefix}가장 추천하는 곳은 ${state.anchorCoord.label}에서 ${dist1} 거리인 『${top1.name}』(${status1})이에요. ${top1.summary}`;
  if (top1.outlets) {
    reply += ` (콘센트: ${top1.outlets})`;
  }
  if (top2 && top3) {
    reply += ` 이어서 『${top2.name}』(${formatDistanceLabel(
      top2.distance
    )})과 『${top3.name}』(${formatDistanceLabel(
      top3.distance
    )})도 조건에 잘 맞으니 아래 카드를 눌러 비교해 보세요!`;
  } else if (top2) {
    reply += ` 함께 추천된 『${top2.name}』(${formatDistanceLabel(
      top2.distance
    )})도 좋은 선택지예요!`;
  }
  return reply;
}

async function requestRealGeminiConversationalReply(effectiveQuery, topPicks) {
  const apiKey = getStoredGeminiApiKey();
  if (!apiKey || !effectiveQuery || !topPicks || topPicks.length === 0) return;

  const cacheKey = `${state.campus}:${state.anchorKey}:${effectiveQuery}`;
  if (geminiReplyCache.has(cacheKey)) {
    const cachedText = geminiReplyCache.get(cacheKey);
    const bubbleEl = document.getElementById("aiConversationalBubbleText");
    const modeTagEl = document.getElementById("aiEngineModeTag");
    if (bubbleEl) bubbleEl.textContent = cachedText;
    if (modeTagEl) modeTagEl.textContent = "⚡ Gemini 2.5 Flash 답변";
    return;
  }

  const modeTagEl = document.getElementById("aiEngineModeTag");
  if (modeTagEl) modeTagEl.textContent = "⚡ Gemini 2.5 생성 중…";

  const candidateSummary = topPicks
    .slice(0, 4)
    .map((item, idx) => {
      const p = item.place;
      return `${idx + 1}위: ${p.name} (${state.anchorCoord.label}에서 ${formatDistanceLabel(
        p.distance
      )}, ${p.businessStatus?.label || ""}, 콘센트:${p.outlets}, 특징:${p.summary})`;
    })
    .join("\n");

  const promptText = [
    `당신은 경희대 카공맵의 친절한 마스코트 '제발요'입니다.`,
    `학생의 질문/조건: "${effectiveQuery}"`,
    `현재 추천 후보 데이터:\n${candidateSummary}`,
    `위 실제 데이터만 바탕으로 1위~3위 카페의 거리, 영업상태, 콘센트/분위기 장점을 담아 2~3문장(160자 내외)의 다정하고 자연스러운 한국어 대화체로 추천 이유를 브리핑해 주세요.`,
  ].join("\n\n");

  try {
    const res = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${encodeURIComponent(
        apiKey
      )}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: promptText }] }],
          generationConfig: {
            temperature: 0.45,
            maxOutputTokens: 240,
          },
        }),
      }
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    const text =
      data?.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || "";
    if (text) {
      geminiReplyCache.set(cacheKey, text);
      const bubbleEl = document.getElementById("aiConversationalBubbleText");
      const tagAfter = document.getElementById("aiEngineModeTag");
      if (bubbleEl) bubbleEl.textContent = text;
      if (tagAfter) tagAfter.textContent = "⚡ Gemini 2.5 Flash 답변";
    }
  } catch (_err) {
    const tagErr = document.getElementById("aiEngineModeTag");
    if (tagErr) tagErr.textContent = "💬 제발요 대화형 브리핑";
  }
}

function renderAiPromptResultBox(refDate) {
  const box = document.getElementById("aiPromptResultBox");
  const clearBtn = document.getElementById("btnClearAiPrompt");
  if (!box) return;

  const hasPrompt = Boolean(state.aiPromptQuery && state.aiPromptQuery.trim());
  const hasFilter = Boolean(state.selectedMood || state.selectedDetails.size > 0);
  if (clearBtn) clearBtn.classList.toggle("hidden", !hasPrompt);

  if (!hasPrompt && !hasFilter) {
    box.classList.add("hidden");
    return;
  }

  let effectiveQuery = hasPrompt ? state.aiPromptQuery : "";
  if (!effectiveQuery) {
    const parts = [];
    if (state.selectedMood) {
      const m = MOOD_CARDS.find((c) => c.id === state.selectedMood);
      if (m) parts.push(m.label);
    }
    state.selectedDetails.forEach((k) => {
      const c = DETAIL_CONDITIONS.find((d) => d.key === k);
      if (c) parts.push(c.label);
    });
    effectiveQuery = parts.join(" ");
  }

  const basePlaces = applyMoodAndDetails(
    getBaseFilteredPlaces(refDate),
    state.selectedMood,
    state.selectedDetails,
    refDate
  );
  const { intent, topPicks } = scorePlacesByAiPrompt(
    basePlaces,
    effectiveQuery,
    refDate
  );

  if (topPicks.length === 0) {
    box.innerHTML = `
      <div class="ai-prompt-result-header">
        <div class="ai-prompt-title-group">
          <img src="./assets/fairy/fairy-trio.webp?v=20261102_6" alt="제발요" class="ai-result-trio-img" width="34" height="22" />
          <span class="ai-prompt-badge">제발요 추천</span>
          <span class="ai-prompt-summary-text">조건에 맞는 카페를 찾지 못했어요. 다른 조건으로 검색해 보세요!</span>
        </div>
      </div>
    `;
    box.classList.remove("hidden");
    return;
  }

  const reasonSummary =
    hasPrompt && intent.reasons.length > 0
      ? `${intent.reasons.join(" · ")} 맞춤 추천`
      : `"${escapeHtmlSafe(effectiveQuery)}" 추천 TOP ${topPicks.length}`;

  const conversationalText = buildConversationalFairyReply(
    effectiveQuery,
    intent,
    topPicks
  );
  const hasGeminiKey = Boolean(getStoredGeminiApiKey());
  const engineTagLabel = hasGeminiKey
    ? "⚡ Gemini 2.5 Flash 연동"
    : "💬 제발요 대화형 브리핑";

  const picksHtml = topPicks
    .map((item, idx) => {
      const p = item.place;
      const distLabel = formatDistanceLabel(p.distance);
      const badgeReason =
        item.matchedReasons.slice(0, 2).join("·") ||
        p.tags.slice(0, 2).map((t) => TAG_DISPLAY_LABELS[t] || t).join("·");
      return `
        <button type="button" class="ai-pick-chip" data-ai-pick-id="${p.id}">
          <span class="ai-pick-rank">${idx + 1}위</span>
          <span class="ai-pick-name">${escapeHtmlSafe(p.name)}</span>
          <span class="ai-pick-meta">${state.anchorCoord.label} ${distLabel}${badgeReason ? ` · ${badgeReason}` : ""}</span>
        </button>
      `;
    })
    .join("");

  box.innerHTML = `
    <div class="ai-prompt-result-header">
      <div class="ai-prompt-title-group">
        <img src="./assets/fairy/fairy-trio.webp?v=20261102_6" alt="제발요" class="ai-result-trio-img" width="34" height="22" />
        <span class="ai-prompt-badge">제발요 추천</span>
        <span class="ai-prompt-summary-text">${reasonSummary}</span>
        <span class="ai-engine-mode-tag" id="aiEngineModeTag">${engineTagLabel}</span>
      </div>
      <button type="button" class="ai-prompt-share-btn" id="btnShareAiPrompt" title="추천 링크 복사" aria-label="추천 링크 복사">
        <span aria-hidden="true">🔗</span>
      </button>
    </div>
    <div class="ai-conversational-bubble" id="aiConversationalBubble">
      <p class="ai-conversational-text" id="aiConversationalBubbleText">${escapeHtmlSafe(
        conversationalText
      )}</p>
    </div>
    <div class="ai-pick-chips-row">${picksHtml}</div>
  `;
  box.classList.remove("hidden");

  if (hasGeminiKey) {
    requestRealGeminiConversationalReply(effectiveQuery, topPicks);
  }

  box.querySelectorAll("[data-ai-pick-id]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const pid = Number(btn.dataset.aiPickId);
      openPlaceDetail(pid, true);
    });
  });

  const shareBtn = document.getElementById("btnShareAiPrompt");
  if (shareBtn) {
    shareBtn.addEventListener("click", () => {
      copyShareLink();
      showToast("🔗 이 추천 조건이 담긴 사이트 링크가 복사되었어요!");
    });
  }
}

// 12. 선 아이콘(Lucide SVG, stroke-width 1.75) 생성 헬퍼 (이모지 완전 배제)
function getFeatureIconSvg(type) {
  if (type === "outlet") {
    return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22v-5"></path><path d="M9 8V2"></path><path d="M15 8V2"></path><path d="M18 8v5a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4V8Z"></path></svg>`;
  }
  if (type === "solo") {
    return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>`;
  }
  if (type === "quiet") {
    return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><line x1="22" y1="9" x2="16" y2="15"></line><line x1="16" y1="9" x2="22" y2="15"></line></svg>`;
  }
  if (type === "group") {
    return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87"></path><path d="M16 3.13a4 4 0 0 1 0 7.75"></path></svg>`;
  }
  return `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 8h1a4 4 0 1 1 0 8h-1"></path><path d="M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z"></path></svg>`;
}

function buildPlaceFeatureIconsHtml(place) {
  const features = [];
  if (place.tags.includes("콘센트많음")) {
    features.push({ icon: getFeatureIconSvg("outlet"), label: "콘센트" });
  }
  if (place.tags.includes("1인석")) {
    features.push({ icon: getFeatureIconSvg("solo"), label: "1인석" });
  }
  if (place.tags.includes("조용한")) {
    features.push({ icon: getFeatureIconSvg("quiet"), label: "조용" });
  }
  if (features.length < 3 && place.tags.includes("단체석")) {
    features.push({ icon: getFeatureIconSvg("group"), label: "단체석" });
  }

  return features
    .slice(0, 3)
    .map(
      (f) =>
        `<span class="feature-icon-item" title="${f.label}">${f.icon}<span>${f.label}</span></span>`
    )
    .join("");
}

// 13. 상황 카드 및 세부 조건 DOM 초기화 (최초 1회 생성 후 클래스·텍스트만 제자리 업데이트)
function mountMoodCardsOnce() {
  const track = document.getElementById("moodCardsTrack");
  if (!track || track.children.length > 0) return;

  const sparkleSvg = `
    <svg class="mood-sparkle-dot" viewBox="0 0 16 16" aria-hidden="true">
      <defs>
        <linearGradient id="rainbowSparkleGrad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stop-color="#4285F4" />
          <stop offset="52%" stop-color="#8B5CF6" />
          <stop offset="100%" stop-color="#D96570" />
        </linearGradient>
      </defs>
      <path fill="url(#rainbowSparkleGrad)" d="M8 0L9.8 6.2L16 8L9.8 9.8L8 16L6.2 9.8L0 8L6.2 6.2Z" />
    </svg>
  `;

  MOOD_CARDS.forEach((mood) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "mood-card";
    btn.dataset.moodId = mood.id;
    btn.setAttribute("role", "radio");
    btn.setAttribute("aria-checked", "false");
    btn.setAttribute("aria-label", mood.label);
    btn.innerHTML = `
      <span class="mood-card-text">${mood.label}</span>
      <span class="mood-card-meta">
        ${sparkleSvg}
        <span class="mood-count-badge" data-mood-count="${mood.id}">0곳</span>
      </span>
    `;
    track.appendChild(btn);
  });
}

function updateMoodCardsInPlace(refDate) {
  mountMoodCardsOnce();
  const basePlaces = getBaseFilteredPlaces(refDate);

  MOOD_CARDS.forEach((mood) => {
    const matching = applyMoodAndDetails(
      basePlaces,
      mood.id,
      state.selectedDetails,
      refDate
    );
    const count = matching.length;
    const cardEl = document.querySelector(`.mood-card[data-mood-id="${mood.id}"]`);
    if (!cardEl) return;

    const isSelected = state.selectedMood === mood.id;
    cardEl.classList.toggle("is-selected", isSelected);
    cardEl.classList.toggle("is-empty", count === 0 && !isSelected);
    cardEl.setAttribute("aria-checked", isSelected ? "true" : "false");
    cardEl.dataset.currentCount = String(count);

    const countEl = cardEl.querySelector(`[data-mood-count="${mood.id}"]`);
    if (countEl) {
      countEl.textContent = `${count}곳`;
    }
  });

  // 통합 검색창 상태 동기화 (선택된 카공 카드 / 세부 조건 / AI 검색어 요약 표시)
  const detailBtn = document.getElementById("btnOpenDetailFilter");
  const detailLabel = document.getElementById("detailFilterBtnLabel");
  const greetingText = document.getElementById("greetingText");
  const btnInlineReset = document.getElementById("btnInlineDetailReset");

  const activeParts = [];
  if (state.aiPromptQuery && state.aiPromptQuery.trim()) {
    activeParts.push(`"${state.aiPromptQuery.trim()}"`);
  }
  if (state.selectedMood) {
    const m = MOOD_CARDS.find((c) => c.id === state.selectedMood);
    if (m) activeParts.push(m.label);
  }
  state.selectedDetails.forEach((k) => {
    const c = DETAIL_CONDITIONS.find((d) => d.key === k);
    if (c) activeParts.push(c.label);
  });

  const hasAnyActiveSearch = activeParts.length > 0;
  if (detailBtn) {
    detailBtn.classList.toggle("has-active", hasAnyActiveSearch);
  }
  if (greetingText) {
    greetingText.textContent = hasAnyActiveSearch
      ? activeParts.join(" · ")
      : "원하는 카공 카드나 세부 조건을 검색해보세요";
  }
  if (detailLabel) {
    detailLabel.textContent = hasAnyActiveSearch ? `${activeParts.length}` : "";
    detailLabel.classList.toggle("hidden", !hasAnyActiveSearch);
  }
  if (btnInlineReset) {
    btnInlineReset.classList.toggle("hidden", !hasAnyActiveSearch);
  }
}

function mountDetailChipsOnce() {
  const grid = document.getElementById("detailChipGrid");
  if (grid && grid.children.length === 0) {
    DETAIL_CONDITIONS.forEach((cond) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "detail-cond-chip";
      btn.dataset.condKey = cond.key;
      btn.setAttribute("aria-pressed", "false");
      btn.setAttribute("aria-label", cond.label);
      btn.innerHTML = `
        <span>${cond.label}</span>
        <span class="cond-remain-count" data-cond-count="${cond.key}">0곳</span>
      `;
      grid.appendChild(btn);
    });
  }

  const inlineTrack = document.getElementById("inlineDetailTrack");
  if (inlineTrack && inlineTrack.children.length === 0) {
    DETAIL_CONDITIONS.forEach((cond) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "detail-cond-chip";
      btn.dataset.condKey = cond.key;
      btn.setAttribute("aria-pressed", "false");
      btn.setAttribute("aria-label", cond.label);
      btn.innerHTML = `
        <span>${cond.label}</span>
        <span class="cond-remain-count" data-cond-count="${cond.key}">0곳</span>
      `;
      inlineTrack.appendChild(btn);
    });
  }
}

function updateDetailChipsInPlace(refDate) {
  mountDetailChipsOnce();
  const basePlaces = getBaseFilteredPlaces(refDate);

  DETAIL_CONDITIONS.forEach((cond) => {
    const isSelected = state.selectedDetails.has(cond.key);
    const hypotheticalSet = new Set(state.selectedDetails);
    hypotheticalSet.add(cond.key);

    const remaining = applyMoodAndDetails(
      basePlaces,
      state.selectedMood,
      hypotheticalSet,
      refDate
    ).length;

    document
      .querySelectorAll(`.detail-cond-chip[data-cond-key="${cond.key}"]`)
      .forEach((chipEl) => {
        chipEl.classList.toggle("is-selected", isSelected);
        chipEl.classList.toggle("is-zero", remaining === 0 && !isSelected);
        chipEl.setAttribute("aria-pressed", isSelected ? "true" : "false");
        chipEl.dataset.remainCount = String(remaining);

        const countSpan = chipEl.querySelector(`[data-cond-count="${cond.key}"]`);
        if (countSpan) {
          countSpan.textContent = `${remaining}곳`;
        }
      });
  });

  const btnInlineReset = document.getElementById("btnInlineDetailReset");
  if (btnInlineReset) {
    const hasAnyActive =
      Boolean(state.selectedMood) ||
      state.selectedDetails.size > 0 ||
      Boolean(state.aiPromptQuery && state.aiPromptQuery.trim());
    btnInlineReset.classList.toggle("hidden", !hasAnyActive);
  }
}

// 14. 상단 헤더, 필터 칩 한 줄(선택된 칩만 색 표시), 아래 패널 제목("카페 N곳 · 영업 중 M") 렌더링
function renderControlsAndGreeting(displayedPlaces, refDate) {
  // 캠퍼스 세그먼트
  document.querySelectorAll(".campus-btn").forEach((btn) => {
    const active = btn.dataset.campus === state.campus;
    btn.classList.toggle("active", active);
    btn.setAttribute("aria-selected", active ? "true" : "false");
  });

  // 기준점 드롭다운 옵션 동기화
  const selectAnchor = document.getElementById("selectAnchor");
  const chipWrapAnchor = document.getElementById("chipWrapAnchor");
  if (selectAnchor) {
    const anchors = CAMPUS_ANCHORS[state.campus];
    const desiredValues = ["gps", ...anchors.map((a) => a.key)];
    const currentValues = Array.from(selectAnchor.options).map((o) => o.value);
    if (desiredValues.join(",") !== currentValues.join(",")) {
      selectAnchor.innerHTML = [
        `<option value="gps">내 위치</option>`,
        ...anchors.map(
          (a) => `<option value="${a.key}">${a.optionLabel || a.label}</option>`
        ),
      ].join("");
    }
    selectAnchor.value = state.anchorKey;
  }
  if (chipWrapAnchor) {
    chipWrapAnchor.classList.add("is-active");
  }

  // 반경 드롭다운 동기화 (선택된 반경이 있을 때만 칩 색상 표시)
  const selectRadius = document.getElementById("selectRadius");
  const chipWrapRadius = document.getElementById("chipWrapRadius");
  if (selectRadius) {
    selectRadius.value = String(state.radiusMeters);
  }
  if (chipWrapRadius) {
    chipWrapRadius.classList.toggle("is-active", state.radiusMeters > 0);
  }

  // 방문 예정 시각 드롭다운 동기화 (지금 이외 시각 선택 시 칩 색상 표시)
  const selectVisitTime = document.getElementById("selectVisitTime");
  const chipWrapTime = document.getElementById("chipWrapTime");
  if (selectVisitTime) {
    selectVisitTime.value = state.visitTimeMode;
  }
  if (chipWrapTime) {
    chipWrapTime.classList.toggle("is-active", state.visitTimeMode !== "now");
  }

  // 영업 중만 스위치 동기화 (켜졌을 때만 칩 색상 표시)
  const btnOpenNow = document.getElementById("btnToggleOpenNow");
  if (btnOpenNow) {
    btnOpenNow.classList.toggle("active", state.openNowOnly);
    btnOpenNow.classList.toggle("is-active", state.openNowOnly);
    btnOpenNow.setAttribute("aria-checked", state.openNowOnly ? "true" : "false");
  }

  // 밤 시간대(19:00 ~ 05:59) 또는 '밤 10시' 선택 시 지도와 UI 전체를 함께 다크 나이트 모드로 동기화
  const seoulRef = window.HoursEngine.getSeoulTimeParts(refDate);
  const isNightTime = seoulRef.hour >= 19 || seoulRef.hour < 6;
  document.body.classList.toggle("is-night-mode", isNightTime);

  // 아래 패널 제목 ("카페 25곳 · 영업 중 24")
  const summaryEl = document.getElementById("resultCountSummary");
  if (summaryEl) {
    const openCount = displayedPlaces.filter((p) => p.businessStatus.isOpen).length;
    const totalCount = displayedPlaces.length;
    if (state.visitTimeMode === "morning09") {
      summaryEl.textContent = `카페 ${totalCount}곳 · 아침 9시 영업 ${openCount}`;
    } else if (state.visitTimeMode === "afternoon14") {
      summaryEl.textContent = `카페 ${totalCount}곳 · 오후 2시 영업 ${openCount}`;
    } else if (state.visitTimeMode === "tonight22") {
      summaryEl.textContent = `카페 ${totalCount}곳 · 밤 10시 영업 ${openCount}`;
    } else {
      summaryEl.textContent = `카페 ${totalCount}곳 · 영업 중 ${openCount}`;
    }
  }

  // Google AI Pro 링크 캠퍼스 UTM 업데이트
  const ctaLink = document.getElementById("geminiCtaLink");
  if (ctaLink) {
    ctaLink.href = `${GEMINI_BASE_URL}&utm_content=${state.campus}_kagong`;
  }
}

// 15. 5-3절: 컴팩트 목록 카드 렌더링 (높이 96~110px, 3줄 구성)
function renderPlaceList(displayedPlaces) {
  const listView = document.getElementById("sheetListView");
  if (listView) listView.classList.remove("hidden");
  const container = document.getElementById("placeListContainer");
  if (!container) return;

  if (displayedPlaces.length === 0) {
    const reasonText = state.openNowOnly
      ? "여긴 아직 비어 있어요. 반경을 넓히거나 영업 종료된 곳도 함께 볼까요?"
      : "여긴 아직 비어 있어요. 반경을 넓혀볼까요?";

    container.innerHTML = `
      <div class="empty-state-box">
        <div class="fairy-gemini-halo">
          <img
            src="./assets/fairy/fairy-sleep.webp?v=20261102_6"
            alt="별을 베고 졸고 있는 요정"
            class="empty-fairy-img fairy-float"
            id="emptySleepFairyImg"
            width="136"
            height="106"
            loading="lazy"
          />
        </div>
        <p class="empty-state-title">${reasonText}</p>
        <p class="empty-state-sub">${state.anchorCoord.label} 기준 조건에 맞는 카페가 없어요.</p>
        <div class="empty-action-row">
          ${
            state.visitTimeMode !== "morning09"
              ? `<button type="button" class="secondary-pill-btn" id="btnEmptyMorning09" aria-label="내일 아침 9시 영업 카페 보기">내일 아침 9시 카페 보기</button>`
              : ""
          }
          ${
            state.radiusMeters !== 0
              ? `<button type="button" class="secondary-pill-btn" id="btnEmptyExpandRadius" aria-label="탐색 반경 전체로 넓히기">반경 넓히기</button>`
              : ""
          }
          ${
            state.openNowOnly
              ? `<button type="button" class="secondary-pill-btn" id="btnEmptyShowClosed" aria-label="영업 종료된 카페도 함께 보기">닫은 곳도 보기</button>`
              : ""
          }
          ${
            state.selectedMood || state.selectedDetails.size > 0
              ? `<button type="button" class="secondary-pill-btn" id="btnEmptyResetFilters" aria-label="선택한 조건 초기화">조건 초기화</button>`
              : ""
          }
        </div>
      </div>
    `;

    const emptyFairyImg = document.getElementById("emptySleepFairyImg");
    if (emptyFairyImg) {
      emptyFairyImg.addEventListener("click", () => {
        triggerFairySparkleAndHop(emptyFairyImg);
        showToast("제발요가 깨어났어요! 반경을 넓히거나 닫은 곳도 함께 볼까요?");
      });
    }
    const btnEmptyMorning09 = document.getElementById("btnEmptyMorning09");
    if (btnEmptyMorning09) {
      btnEmptyMorning09.addEventListener("click", () => {
        state.visitTimeMode = "morning09";
        state.openNowOnly = true;
        state._customGreetingLocked = false;
        trackEvent("change_visit_time", { mode: "morning09", source: "empty_state" });
        renderAll(false);
      });
    }
    const btnExpand = document.getElementById("btnEmptyExpandRadius");
    if (btnExpand) {
      btnExpand.addEventListener("click", () => {
        state.radiusMeters = state.radiusMeters === 300 ? 500 : state.radiusMeters === 500 ? 1000 : 0;
        renderAll();
      });
    }
    const btnShowClosed = document.getElementById("btnEmptyShowClosed");
    if (btnShowClosed) {
      btnShowClosed.addEventListener("click", () => {
        state.openNowOnly = false;
        trackEvent("toggle_open_now", { open_now_only: false, source: "empty_state" });
        renderAll();
      });
    }
    const btnReset = document.getElementById("btnEmptyResetFilters");
    if (btnReset) {
      btnReset.addEventListener("click", () => {
        state.selectedMood = null;
        state.selectedDetails.clear();
        renderAll();
      });
    }
    return;
  }

  const hasActiveSearch =
    Boolean(state.aiPromptQuery && state.aiPromptQuery.trim()) ||
    Boolean(state.selectedMood) ||
    state.selectedDetails.size > 0;

  container.innerHTML = displayedPlaces
    .map((place, idx) => {
      const st = place.businessStatus;
      const isClosedCard = !st.isOpen;
      const isSelectedCard = place.id === state.selectedPlaceId;
      const isAiTopPick = hasActiveSearch && idx < 3;
      const distText = `${state.anchorCoord.label} ${formatDistanceLabel(place.distance)}`;
      const featureIconsHtml = buildPlaceFeatureIconsHtml(place);

      const statusBadgeHtml =
        st.state === "temp_closed"
          ? `<span class="gray-badge">임시휴업</span>`
          : `<span class="status-text state-${st.state}">${st.label}</span>`;

      const aiRankBadgeHtml = isAiTopPick
        ? `<span class="card-ai-pick-badge">${idx === 0 ? "✨ 1위 추천" : `${idx + 1}위 추천`}</span>`
        : "";

      return `
        <article
          class="place-card ${isClosedCard ? "is-closed-card" : ""} ${isSelectedCard ? "is-selected-card" : ""} ${isAiTopPick ? "is-ai-recommended-card" : ""}"
          data-place-id="${place.id}"
          role="listitem"
          tabindex="0"
          aria-label="${place.name}, ${distText}, ${st.label}"
        >
          <div class="card-row-1">
            <div class="card-title-group">
              ${aiRankBadgeHtml}
              <h3 class="card-place-name">${place.name}</h3>
            </div>
            <span class="card-distance">${distText}</span>
          </div>
          <div class="card-row-2">
            ${statusBadgeHtml}
          </div>
          <div class="card-row-3">
            ${
              featureIconsHtml
                ? `<div class="feature-icons-group">${featureIconsHtml}</div>`
                : ""
            }
            <p class="card-summary-one-line">${place.summary}</p>
          </div>
        </article>
      `;
    })
    .join("");
}

// 16. 5-3 & 3-3절: 카페 상세 시트 렌더링 (대표 사진 히어로 배너 + 3D 요정 길안내 + 네이버·카카오 후기 + 요일별 영업시간 표)
function openPlaceDetail(placeId, panMap = true) {
  const refDate = getEffectiveReferenceDate();
  const activePlaces = window.HoursEngine.filterActivePlaces(state.places);
  const rawPlace = activePlaces.find((p) => p.id === Number(placeId));
  if (!rawPlace) return;

  stopFairyNavigation(false);
  state.selectedPlaceId = rawPlace.id;

  const effectiveAnchor =
    rawPlace.campus !== state.campus && CAMPUS_ANCHORS[rawPlace.campus]
      ? CAMPUS_ANCHORS[rawPlace.campus].find((a) => a.key === state.anchorKey) ||
        CAMPUS_ANCHORS[rawPlace.campus][0]
      : state.anchorCoord;

  const distance = getDistanceMeters(
    effectiveAnchor.lat,
    effectiveAnchor.lng,
    rawPlace.lat,
    rawPlace.lng
  );
  const walkMinutes = Math.max(1, Math.round((distance * 1.28) / 67));
  const heroPhotoUrl = getPlaceHeroPhotoUrl(rawPlace);

  const st = window.HoursEngine.getPlaceBusinessStatus(rawPlace, refDate);
  const verifiedInfo = window.HoursEngine.evaluateVerifiedAt(
    rawPlace.verified_at,
    refDate
  );
  const weeklyRows = window.HoursEngine.getFormattedWeeklyHours(rawPlace);
  const seoulNow = window.HoursEngine.getSeoulTimeParts(refDate);

  const listView = document.getElementById("sheetListView");
  const detailView = document.getElementById("sheetDetailView");
  const navView = document.getElementById("sheetFairyNavView");
  if (!listView || !detailView) return;
  if (navView) navView.classList.add("hidden");

  const { naverUrl, kakaoUrl } = getPlaceExternalLinks(rawPlace);

  const tagsHtml = rawPlace.tags
    .map((t) => {
      const label = TAG_DISPLAY_LABELS[t] || t;
      return `<span class="detail-tag-pill">${label}</span>`;
    })
    .join("");

  const weeklyTableHtml = weeklyRows
    .map((r) => {
      const isToday = r.dayIndex === seoulNow.dayOfWeek;
      return `
        <tr class="${isToday ? "is-today" : ""} ${r.isClosed ? "is-closed-day" : ""}">
          <td class="day-col">${r.dayLabel}${isToday ? " (오늘)" : ""}</td>
          <td>${r.timeLabel}</td>
        </tr>
      `;
    })
    .join("");

  const extraMetaRows = [];
  if (rawPlace.break_time) {
    extraMetaRows.push(`브레이크타임 ${rawPlace.break_time}`);
  }
  if (rawPlace.last_order) {
    extraMetaRows.push(`라스트오더 ${rawPlace.last_order}`);
  }
  if (rawPlace.closed_days) {
    extraMetaRows.push(`정기휴무 ${rawPlace.closed_days}`);
  }

  detailView.innerHTML = `
    <!-- 카페 이름 뒤에 깔리는 대표 사진 히어로 배너 -->
    <div class="detail-hero-card" style="background-image: url('${heroPhotoUrl}');">
      <img
        src="${heroPhotoUrl}"
        alt="${rawPlace.name} 실제 매장 대표 사진"
        class="detail-hero-photo"
        onerror="this.onerror=null;"
      />
      <div class="detail-hero-scrim" aria-hidden="true"></div>
      <div class="detail-hero-aurora-glow" aria-hidden="true"></div>

      <div class="detail-hero-top-bar">
        <button type="button" class="hero-glass-back-btn" id="btnBackToList" aria-label="목록으로 돌아가기">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <line x1="19" y1="12" x2="5" y2="12"></line>
            <polyline points="12 19 5 12 12 5"></polyline>
          </svg>
          <span>목록으로</span>
        </button>

        <div class="hero-top-right-group">
          <span class="hero-glass-dist-pill">
            ${effectiveAnchor.label} ${formatDistanceLabel(distance)} · 도보 ${walkMinutes}분
          </span>
          <button type="button" class="hero-glass-icon-btn" id="btnDetailShare" aria-label="이 카페 공유 링크 복사">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <circle cx="18" cy="5" r="3"></circle>
              <circle cx="6" cy="12" r="3"></circle>
              <circle cx="18" cy="19" r="3"></circle>
              <line x1="8.59" y1="13.51" x2="15.42" y2="17.49"></line>
              <line x1="15.41" y1="6.51" x2="8.59" y2="10.49"></line>
            </svg>
          </button>
        </div>
      </div>

      <div class="detail-hero-bottom">
        <div class="detail-hero-title-row">
          <h2 class="detail-place-name">${rawPlace.name}</h2>
        </div>
        <div class="detail-hero-status-row">
          ${
            st.state === "temp_closed"
              ? `<span class="hero-status-pill state-temp_closed">임시휴업</span>`
              : `<span class="hero-status-pill state-${st.state}">${st.label}</span>`
          }
          <span class="hero-verified-text">
            <span>· ${verifiedInfo.relativeLabel}</span>
            ${
              verifiedInfo.isStale
                ? `<span class="hero-stale-badge">정보 확인 필요</span>`
                : ""
            }
          </span>
        </div>
      </div>
    </div>

    <div class="detail-header-block">
      <p class="detail-summary-text">${rawPlace.summary}</p>
      ${tagsHtml ? `<div class="detail-tag-row">${tagsHtml}</div>` : ""}

      <!-- 제발요에게 길 안내 받기 + 네이버 지도·후기 + 카카오맵·후기 통합 허브 -->
      <div class="detail-navigation-hub">
        <button
          type="button"
          class="fairy-route-cta-btn"
          id="btnStartFairyRoute"
          aria-label="제발요에게 이 카페까지 길 안내 받기"
        >
          <div class="fairy-route-cta-left">
            <div class="fairy-gemini-halo">
              <img
                src="./assets/fairy/fairy-fly.webp?v=20261102_6"
                alt=""
                class="fairy-route-btn-img fairy-float"
                width="44"
                height="40"
              />
            </div>
            <div class="fairy-route-cta-text-col">
              <span class="fairy-route-cta-title">제발요에게 길 안내 받기</span>
              <span class="fairy-route-cta-sub">${effectiveAnchor.label}에서 도보 약 ${walkMinutes}분 · 제발요가 내 위치를 추적해 안내해요</span>
            </div>
          </div>
          <span class="fairy-route-cta-arrow">길안내 시작 ➔</span>
        </button>

        <div class="detail-ext-links">
          <a
            href="${naverUrl}"
            target="_blank"
            rel="noopener noreferrer"
            class="ext-link-btn naver-btn"
            data-ext-type="naver_map"
            aria-label="네이버 지도에서 사진 및 방문자 후기 보기"
          >
            <span class="ext-brand-dot naver" aria-hidden="true"></span>
            <span>네이버 지도 · 후기</span>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <line x1="7" y1="17" x2="17" y2="7"></line>
              <polyline points="7 7 17 7 17 17"></polyline>
            </svg>
          </a>
          <a
            href="${kakaoUrl}"
            target="_blank"
            rel="noopener noreferrer"
            class="ext-link-btn kakao-btn"
            data-ext-type="kakao_map"
            aria-label="카카오맵에서 후기 및 위치 보기"
          >
            <span class="ext-brand-dot kakao" aria-hidden="true"></span>
            <span>카카오맵 · 후기</span>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <line x1="7" y1="17" x2="17" y2="7"></line>
              <polyline points="7 7 17 7 17 17"></polyline>
            </svg>
          </a>
        </div>
      </div>
    </div>

    <div class="detail-info-section">
      <div class="detail-info-item">
        <span class="detail-info-icon" aria-hidden="true">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">
            <path d="M12 22v-5"></path>
            <path d="M9 8V2"></path>
            <path d="M15 8V2"></path>
            <path d="M18 8v5a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4V8Z"></path>
          </svg>
        </span>
        <div class="detail-info-content">
          <div class="detail-info-label">콘센트 및 좌석 환경</div>
          <div class="detail-info-value">${rawPlace.outlets}</div>
        </div>
      </div>

      <div class="detail-info-item">
        <span class="detail-info-icon" aria-hidden="true">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="10"></circle>
            <polyline points="12 6 12 12 16 14"></polyline>
          </svg>
        </span>
        <div class="detail-info-content">
          <div class="detail-hours-header-row">
            <div class="detail-info-label" style="margin-bottom:0;">요일별 영업시간</div>
            <button
              type="button"
              class="detail-refresh-hours-btn"
              id="btnRefreshPlaceHours"
              aria-label="이 매장 최신 영업정보 다시 확인"
            >
              <svg class="refresh-svg-icon" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <polyline points="23 4 23 10 17 10"></polyline>
                <polyline points="1 20 1 14 7 14"></polyline>
                <path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"></path>
              </svg>
              <span>최신 영업정보 갱신</span>
            </button>
          </div>
          <table class="weekly-hours-table" aria-label="요일별 영업시간">
            <tbody>${weeklyTableHtml}</tbody>
          </table>
          ${
            extraMetaRows.length > 0
              ? `<div class="detail-verified-row" style="margin-top:6px;">${extraMetaRows.join(" · ")}</div>`
              : ""
          }
        </div>
      </div>

      ${
        rawPlace.note
          ? `
      <div class="detail-info-item">
        <span class="detail-info-icon" aria-hidden="true">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="10"></circle>
            <line x1="12" y1="16" x2="12" y2="12"></line>
            <line x1="12" y1="8" x2="12.01" y2="8"></line>
          </svg>
        </span>
        <div class="detail-info-content">
          <div class="detail-info-label">참고 사항</div>
          <div class="detail-info-value">${rawPlace.note}</div>
        </div>
      </div>`
          : ""
      }
    </div>

    <!-- 경희인 카공 한줄 후기 남기기 & 실시간 후기 목록 -->
    <div class="detail-review-section" id="detailReviewSection">
      <div class="detail-review-header">
        <span class="detail-review-title">💬 경희인 카공 후기</span>
        <span class="detail-review-count" id="detailReviewCountLabel">${getPlaceReviews(rawPlace).length}개</span>
      </div>
      <div class="detail-review-tag-row" id="detailReviewTagRow" role="group" aria-label="후기 키워드 선택">
        <button type="button" class="review-vibe-chip is-selected" data-vibe-tag="콘센트 넉넉">⚡ 콘센트 넉넉</button>
        <button type="button" class="review-vibe-chip" data-vibe-tag="조용해요">🤫 조용해요</button>
        <button type="button" class="review-vibe-chip" data-vibe-tag="좌석 편해요">🪑 좌석 편해요</button>
        <button type="button" class="review-vibe-chip" data-vibe-tag="커피·디저트 맛집">☕ 커피·디저트 맛집</button>
        <button type="button" class="review-vibe-chip" data-vibe-tag="밤공부 최고">🌙 밤공부 최고</button>
      </div>
      <div class="detail-review-form-row">
        <input
          type="text"
          id="detailReviewInput"
          class="detail-review-input"
          placeholder="콘센트 위치, 분위기 등 카공 후기를 남겨주세요!"
          maxlength="120"
          aria-label="카공 한줄 후기 입력"
        />
        <button type="button" class="detail-review-submit-btn" id="btnSubmitDetailReview">
          등록
        </button>
      </div>
      <div class="detail-review-list" id="detailReviewList">
        ${getPlaceReviews(rawPlace)
          .map(
            (rev) => `
          <div class="detail-review-item">
            <div class="detail-review-meta">
              <span class="detail-review-tag-badge">${escapeHtmlSafe(rev.tag)}</span>
              <span>${escapeHtmlSafe(rev.author)} · ${escapeHtmlSafe(rev.date)}</span>
            </div>
            <p class="detail-review-text">${escapeHtmlSafe(rev.text)}</p>
          </div>
        `
          )
          .join("")}
      </div>
    </div>

    <div class="detail-report-row" style="gap: 8px; flex-wrap: wrap;">
      ${
        REPORT_FORM_URL && REPORT_FORM_URL.trim()
          ? `
      <a
        href="${REPORT_FORM_URL.trim()}"
        target="_blank"
        rel="noopener noreferrer"
        class="report-link-btn"
        id="btnReportInfo"
        aria-label="영업시간이나 정보가 다른 경우 제보하기"
      >
        <span>정보가 달라요 (수정 제보)</span>
      </a>`
          : ""
      }
      <button
        type="button"
        class="report-link-btn"
        id="btnDetailSuggestCafe"
        aria-label="새로운 카공 카페 건의하기"
      >
        <span>+ 새 카페 건의하기</span>
      </button>
    </div>
  `;

  const sheet = document.getElementById("mainBottomSheet");
  if (sheet) {
    sheet.classList.remove("hidden", "is-fairy-nav");
  }
  detailView.classList.remove("hidden");

  highlightSelectedMarkerOnMap(rawPlace.id);
  if (panMap && leafletMap) {
    leafletMap.panTo([rawPlace.lat, rawPlace.lng], { animate: true });
  }

  const btnBack = document.getElementById("btnBackToList");
  if (btnBack) {
    const backSpan = btnBack.querySelector("span");
    if (backSpan) {
      backSpan.textContent = state.activeMainView === "list" ? "목록으로" : "지도로";
    }
    btnBack.addEventListener("click", () => {
      closePlaceDetail();
    });
  }

  const btnDetailShare = document.getElementById("btnDetailShare");
  if (btnDetailShare) {
    btnDetailShare.addEventListener("click", () => {
      copyShareLink(rawPlace.id);
    });
  }

  const btnStartFairyRoute = document.getElementById("btnStartFairyRoute");
  if (btnStartFairyRoute) {
    btnStartFairyRoute.addEventListener("click", () => {
      // 이미 확보된 내 위치(GPS)가 목적지 주변(3km 이내)이면 'gps'(내 위치 출발)로 바로 시작
      const hasNearbyGps =
        state.userGpsCoord &&
        state.userGpsCoord.lat &&
        getDistanceMeters(
          state.userGpsCoord.lat,
          state.userGpsCoord.lng,
          rawPlace.lat,
          rawPlace.lng
        ) <= 3000;
      startFairyNavigation(rawPlace, hasNearbyGps ? "gps" : "anchor");
    });
  }

  const btnRefreshPlaceHours = document.getElementById("btnRefreshPlaceHours");
  if (btnRefreshPlaceHours) {
    btnRefreshPlaceHours.addEventListener("click", () => {
      refreshAllLiveBusinessInfo(rawPlace.id);
    });
  }

  // 한줄 후기 태그 선택 및 등록 이벤트
  let selectedVibeTag = "콘센트 넉넉";
  const reviewTagRow = document.getElementById("detailReviewTagRow");
  const reviewInput = document.getElementById("detailReviewInput");
  const btnSubmitReview = document.getElementById("btnSubmitDetailReview");
  const reviewListEl = document.getElementById("detailReviewList");
  const reviewCountEl = document.getElementById("detailReviewCountLabel");

  if (reviewTagRow) {
    reviewTagRow.addEventListener("click", (e) => {
      const chip = e.target.closest("[data-vibe-tag]");
      if (!chip) return;
      selectedVibeTag = chip.dataset.vibeTag;
      reviewTagRow.querySelectorAll("[data-vibe-tag]").forEach((el) => {
        el.classList.toggle("is-selected", el === chip);
      });
    });
  }

  const submitReviewHandler = () => {
    if (!reviewInput) return;
    const text = reviewInput.value.trim();
    if (!text) {
      showToast("한줄 후기 내용을 입력해 주세요!");
      reviewInput.focus();
      return;
    }
    savePlaceReview(rawPlace.id, selectedVibeTag, text);
    reviewInput.value = "";
    const updatedReviews = getPlaceReviews(rawPlace);
    if (reviewCountEl) {
      reviewCountEl.textContent = `${updatedReviews.length}개`;
    }
    if (reviewListEl) {
      reviewListEl.innerHTML = updatedReviews
        .map(
          (rev) => `
          <div class="detail-review-item">
            <div class="detail-review-meta">
              <span class="detail-review-tag-badge">${escapeHtmlSafe(rev.tag)}</span>
              <span>${escapeHtmlSafe(rev.author)} · ${escapeHtmlSafe(rev.date)}</span>
            </div>
            <p class="detail-review-text">${escapeHtmlSafe(rev.text)}</p>
          </div>
        `
        )
        .join("");
    }
    trackEvent("submit_place_review", {
      place_id: rawPlace.id,
      place_name: rawPlace.name,
      tag: selectedVibeTag,
    });
    showToast(`✨ ${rawPlace.name} 후기가 등록되었어요!`);
  };

  if (btnSubmitReview) {
    btnSubmitReview.addEventListener("click", submitReviewHandler);
  }
  if (reviewInput) {
    reviewInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        submitReviewHandler();
      }
    });
  }

  const btnReport = document.getElementById("btnReportInfo");
  if (btnReport) {
    btnReport.addEventListener("click", (e) => {
      e.preventDefault();
      trackEvent("click_report", {
        place_id: rawPlace.id,
        place_name: rawPlace.name,
      });
      openReportModal(rawPlace);
    });
  }

  const btnDetailSuggest = document.getElementById("btnDetailSuggestCafe");
  if (btnDetailSuggest) {
    btnDetailSuggest.addEventListener("click", () => {
      openSuggestCafeModal();
    });
  }

  detailView.querySelectorAll("a[data-ext-type]").forEach((a) => {
    a.addEventListener("click", () => {
      trackEvent("place_click", {
        place_id: rawPlace.id,
        place_name: rawPlace.name,
        link_type: a.dataset.extType,
      });
    });
  });
}

function closePlaceDetail() {
  stopFairyNavigation(false);
  state.selectedPlaceId = null;
  const sheet = document.getElementById("mainBottomSheet");
  const detailView = document.getElementById("sheetDetailView");
  const navView = document.getElementById("sheetFairyNavView");
  const listView = document.getElementById("sheetListView");
  if (listView) listView.classList.remove("hidden");
  if (navView) navView.classList.add("hidden");
  if (detailView) detailView.classList.add("hidden");
  if (sheet) {
    sheet.classList.add("hidden");
    sheet.classList.remove("is-fairy-nav");
  }
  highlightSelectedMarkerOnMap(null);
}

// =========================================================
// 16-B. 3D 요정 실시간 도보 길안내 엔진 (네이버지도·카카오맵 스타일 상단 HUD + 경로옵션 + 구간별 Turn-by-Turn + 3D 요정 비행)
// =========================================================
let fairyRouteLayerGroup = null;
let fairyFlyingMarker = null;
let fairyAnimFrameId = null;
let currentFairyNavSession = null;

function getCompassDirectionKo(lat1, lng1, lat2, lng2) {
  const dy = lat2 - lat1;
  const dx = (lng2 - lng1) * Math.cos((lat1 * Math.PI) / 180);
  const angle = (Math.atan2(dx, dy) * 180) / Math.PI;
  const deg = (angle + 360) % 360;
  if (deg >= 337.5 || deg < 22.5) return "북쪽";
  if (deg < 67.5) return "북동쪽";
  if (deg < 112.5) return "동쪽";
  if (deg < 157.5) return "남동쪽";
  if (deg < 202.5) return "남쪽";
  if (deg < 247.5) return "남서쪽";
  if (deg < 292.5) return "서쪽";
  return "북서쪽";
}

function getTurnIconSvg(turnType) {
  if (turnType === "left") {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 14 4 9 9 4"></polyline><path d="M20 20v-7a4 4 0 0 0-4-4H4"></path></svg>`;
  }
  if (turnType === "right") {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 14 20 9 15 4"></polyline><path d="M4 20v-7a4 4 0 0 1 4-4h12"></path></svg>`;
  }
  if (turnType === "crosswalk") {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="2"></rect><line x1="7" y1="8" x2="7" y2="16"></line><line x1="12" y1="8" x2="12" y2="16"></line><line x1="17" y1="8" x2="17" y2="16"></line></svg>`;
  }
  if (turnType === "arrive") {
    return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path><circle cx="12" cy="10" r="3"></circle></svg>`;
  }
  // straight / start
  return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg>`;
}

function getDirectExternalWalkLinks(origin, place) {
  const { naverUrl, kakaoUrl } = getPlaceExternalLinks(place);
  // 카카오맵 공식 도보 길찾기 딥링크 (https://map.kakao.com/link/to/목적지명,위도,경도)
  const kakaoWalkUrl = `https://map.kakao.com/link/to/${encodeURIComponent(
    place.name
  )},${place.lat},${place.lng}`;
  // 네이버 지도 플레이스 또는 검색 연결
  const naverWalkUrl = naverUrl;
  return { naverWalkUrl, kakaoWalkUrl, naverUrl, kakaoUrl };
}

function formatArrivalTimeLabel(durationMin) {
  const arr = new Date(Date.now() + durationMin * 60000);
  const hh = arr.getHours();
  const mm = String(arr.getMinutes()).padStart(2, "0");
  const ampm = hh >= 12 ? "오후" : "오전";
  const h12 = hh % 12 === 0 ? 12 : hh % 12;
  return `${ampm} ${h12}:${mm} 도착 예정`;
}

function generateSmartCampusFootpath(origin, place, routeOption = "recommend") {
  const lat1 = origin.lat;
  const lng1 = origin.lng;
  const lat2 = place.lat;
  const lng2 = place.lng;

  const straightDist = getDistanceMeters(lat1, lng1, lat2, lng2);
  const factor = routeOption === "mainroad" ? 1.32 : routeOption === "shortest" ? 1.16 : 1.24;
  const walkDist = Math.max(40, Math.round(straightDist * factor));
  const durationMin = Math.max(1, Math.round(walkDist / 67));
  const stepsCount = Math.max(50, Math.round(walkDist / 0.7));
  const calories = Math.max(4, Math.round(walkDist * 0.045));
  const crosswalkCount = straightDist > 220 ? 1 : 0;
  const dirKo = getCompassDirectionKo(lat1, lng1, lat2, lng2);

  // 경로 옵션에 따라 굴곡이 조금 다른 자연스러운 도보 경유점 생성
  const dLat = lat2 - lat1;
  const dLng = lng2 - lng1;
  const curveBias = routeOption === "mainroad" ? 0.14 : routeOption === "shortest" ? 0.5 : 0.24;
  const wp1 = [lat1 + dLat * 0.32, lng1 + dLng * curveBias];
  const wp2 = [lat1 + dLat * 0.66, lng1 + dLng * (1 - curveBias * 0.6)];
  const wp3 = [lat1 + dLat * 0.86, lng1 + dLng * 0.9];
  const coords = [
    [lat1, lng1],
    wp1,
    wp2,
    wp3,
    [lat2, lng2],
  ];

  const roadHint =
    place.campus === "seoul"
      ? straightDist <= 260
        ? "경희대로·정문 보행로"
        : "회기로 메인 보행거리"
      : origin.label === "중상"
      ? "중상(영통역 중심상가) 보행로"
      : origin.label === "마을"
      ? "마을(정문쪽 동네) 보행로"
      : "중건(정문 건너편) 보행로";

  const seg1Dist = Math.max(15, Math.round(walkDist * 0.35));
  const seg2Dist = Math.max(15, Math.round(walkDist * 0.42));
  const seg3Dist = Math.max(10, walkDist - seg1Dist - seg2Dist);
  const turnDir = dLng >= 0 ? "right" : "left";
  const turnLabel = dLng >= 0 ? "우회전" : "좌회전";

  const steps = [
    {
      badge: "출발",
      turnType: "straight",
      turnLabel: "직진 출발",
      distanceMeters: seg1Dist,
      shortTag: `${origin.label}에서 출발! ✨`,
      coord: [lat1, lng1],
      instruction: `${origin.label}에서 ${dirKo} 방향(${roadHint})으로 ${seg1Dist}m 직진하세요`,
      subText: `${roadHint} 진입 · 보행자 전용 보도 이용`,
      tip: `총 도보 약 ${durationMin}분(${walkDist}m · 약 ${stepsCount}걸음) 코스예요.`,
    },
    {
      badge: "1번째 안내",
      turnType: crosswalkCount > 0 ? "crosswalk" : "straight",
      turnLabel: crosswalkCount > 0 ? "횡단보도 건너 직진" : "보행로 따라 직진",
      distanceMeters: seg2Dist,
      shortTag: `${roadHint} 따라 ${seg2Dist}m 직진 🧚`,
      coord: wp1,
      instruction:
        crosswalkCount > 0
          ? `전방 횡단보도를 건넌 뒤 ${roadHint}을 따라 ${seg2Dist}m 이동하세요`
          : `${roadHint} 메인 보도를 따라 ${seg2Dist}m 직진하세요`,
      subText: `${roadHint} 중심 구간 · 주변 상가 보도 통과`,
      tip: `콘센트 정보: ${place.outlets}`,
    },
    {
      badge: "2번째 안내",
      turnType: turnDir,
      turnLabel: `${turnLabel} 후 ${seg3Dist}m`,
      distanceMeters: seg3Dist,
      shortTag: `${turnLabel} 후 ${seg3Dist}m 앞 매장! ✨`,
      coord: wp2,
      instruction: `${place.name} 골목/건물 방향으로 ${turnLabel} 후 ${seg3Dist}m 이동하세요`,
      subText: `매장 간판 확인 · ${place.hours ? `오늘 영업 ${place.hours}` : "영업시간 확인"}`,
      tip: `카공 포인트: ${place.summary}`,
    },
    {
      badge: "도착",
      turnType: "arrive",
      turnLabel: "목적지 도착",
      distanceMeters: 0,
      shortTag: `${place.name} 도착 완료! 🎉`,
      coord: [lat2, lng2],
      instruction: `${place.name} 도착! 오른쪽/정면 입구로 들어가 카공 명당 자리를 잡아보세요`,
      subText: `${origin.label}에서 총 ${walkDist}m 이동 완료`,
      tip: `${place.note || place.outlets}`,
    },
  ];

  return {
    origin,
    place,
    routeOption,
    coords,
    distanceMeters: walkDist,
    durationMin,
    stepsCount,
    calories,
    crosswalkCount,
    arrivalTimeLabel: formatArrivalTimeLabel(durationMin),
    steps,
  };
}

async function buildFairyWalkingRoute(origin, place, routeOption = "recommend") {
  const fallbackRoute = generateSmartCampusFootpath(origin, place, routeOption);
  if (routeOption !== "recommend") {
    return fallbackRoute;
  }
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 1600);
    const url = `https://router.project-osrm.org/route/v1/foot/${origin.lng},${origin.lat};${place.lng},${place.lat}?overview=full&geometries=geojson&steps=true`;
    const res = await fetch(url, { signal: controller.signal });
    clearTimeout(timer);
    if (!res.ok) return fallbackRoute;
    const data = await res.json();
    if (!data.routes || !data.routes[0] || !data.routes[0].geometry) {
      return fallbackRoute;
    }
    const route = data.routes[0];
    const geoCoords = route.geometry.coordinates.map((c) => [c[1], c[0]]);
    if (geoCoords.length < 2) return fallbackRoute;

    const distMeters = Math.max(
      fallbackRoute.distanceMeters,
      Math.round(route.distance || fallbackRoute.distanceMeters)
    );
    const durationMin = Math.max(1, Math.round(distMeters / 67));
    const stepsCount = Math.max(50, Math.round(distMeters / 0.7));
    const calories = Math.max(4, Math.round(distMeters * 0.045));
    const idx1 = Math.min(geoCoords.length - 1, Math.floor(geoCoords.length * 0.33));
    const idx2 = Math.min(geoCoords.length - 1, Math.floor(geoCoords.length * 0.68));

    const steps = fallbackRoute.steps.map((st, idx) => {
      const mappedCoord =
        idx === 0
          ? geoCoords[0]
          : idx === 1
          ? geoCoords[idx1]
          : idx === 2
          ? geoCoords[idx2]
          : geoCoords[geoCoords.length - 1];
      return {
        ...st,
        coord: mappedCoord,
      };
    });

    return {
      ...fallbackRoute,
      coords: geoCoords,
      distanceMeters: distMeters,
      durationMin,
      stepsCount,
      calories,
      arrivalTimeLabel: formatArrivalTimeLabel(durationMin),
      steps,
    };
  } catch (_err) {
    return fallbackRoute;
  }
}

function speakFairyInstruction(text) {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) {
    showToast(`🧚 제발요 안내: "${text}"`);
    return;
  }
  try {
    window.speechSynthesis.cancel();
    const utter = new SpeechSynthesisUtterance(text);
    utter.lang = "ko-KR";
    utter.rate = 1.05;
    utter.pitch = 1.18;
    window.speechSynthesis.speak(utter);
    showToast("🔊 제발요가 목소리로 길을 안내하고 있어요!");
  } catch (_e) {
    showToast(`🧚 제발요 안내: "${text}"`);
  }
}

let navGpsWatchId = null;
let fairyWalkedPolyline = null;
let fairyActiveGlowPolyline = null;
let fairyActiveMainPolyline = null;
let fairyActiveDashPolyline = null;

function stopLiveNavGpsTracking() {
  if (navGpsWatchId !== null && typeof navigator !== "undefined" && navigator.geolocation) {
    try {
      navigator.geolocation.clearWatch(navGpsWatchId);
    } catch (_e) {}
    navGpsWatchId = null;
  }
}

function updateLiveRoutePolylines(userLat, userLng, bestStepIdx) {
  if (!currentFairyNavSession || !fairyRouteLayerGroup) return;
  const coords = currentFairyNavSession.route.coords || [];
  if (coords.length < 2) return;

  // 내 위치에서 가장 가까운 경로 좌표 인덱스 찾기
  let nearestCoordIdx = 0;
  let minCoordDist = Infinity;
  for (let i = 0; i < coords.length; i++) {
    const d = getDistanceMeters(userLat, userLng, coords[i][0], coords[i][1]);
    if (d < minCoordDist) {
      minCoordDist = d;
      nearestCoordIdx = i;
    }
  }

  const walkedCoords = [...coords.slice(0, nearestCoordIdx + 1), [userLat, userLng]];
  const remainingCoords = [
    [userLat, userLng],
    ...coords.slice(Math.min(coords.length - 1, Math.max(1, nearestCoordIdx + 1))),
  ];

  if (fairyWalkedPolyline) {
    fairyWalkedPolyline.setLatLngs(walkedCoords);
  }
  if (fairyActiveGlowPolyline) {
    fairyActiveGlowPolyline.setLatLngs(remainingCoords);
  }
  if (fairyActiveMainPolyline) {
    fairyActiveMainPolyline.setLatLngs(remainingCoords);
  }
  if (fairyActiveDashPolyline) {
    fairyActiveDashPolyline.setLatLngs(remainingCoords);
  }
}

function updateFairyNavLivePosition(
  lat,
  lng,
  accuracy = 25,
  recenter = false,
  isExplicitMove = false
) {
  if (!currentFairyNavSession) return;
  const { route } = currentFairyNavSession;
  const { place, steps } = route;

  state.userGpsCoord = {
    lat,
    lng,
    accuracy,
    label: "내 위치",
  };

  // 목적지와의 실시간 직선/보행 남은 거리 계산
  const distToDest = Math.round(getDistanceMeters(lat, lng, place.lat, place.lng));

  // 캠퍼스/목적지 반경(3.5km 이내)일 때만 지도 위 제발요 마커를 실제 내 위치로 이동
  if (distToDest > 3500 && !isExplicitMove) {
    return;
  }

  const startCoord = currentFairyNavSession.startCoord || route.coords[0];
  const movedFromStart = Math.round(
    getDistanceMeters(lat, lng, startCoord[0], startCoord[1])
  );
  if (movedFromStart >= 15 || isExplicitMove) {
    currentFairyNavSession.hasMovedFromStart = true;
  }

  currentFairyNavSession.liveUserCoord = [lat, lng];
  currentFairyNavSession.remainingDistMeters = distToDest;

  if (fairyFlyingMarker) {
    fairyFlyingMarker.setLatLng([lat, lng]);
  }
  if (recenter && leafletMap) {
    leafletMap.panTo([lat, lng], { animate: true });
  }

  // ★ 핵심: 길안내 시작 직후에는 절대 바로 도착 처리하지 않고,
  // 사용자가 실제로 이동하여(hasMovedFromStart) 목적지 반경 22m 이내에 도달했을 때만 도착 완료 트리거!
  if (distToDest <= 22 && currentFairyNavSession.hasMovedFromStart) {
    const arriveIdx = steps.length - 1;
    const wasArrived = currentFairyNavSession.hasArrived;
    currentFairyNavSession.hasArrived = true;
    currentFairyNavSession.stepIndex = arriveIdx;
    currentFairyNavSession.remainingDistMeters = 0;

    updateLiveRoutePolylines(place.lat, place.lng, arriveIdx);

    const tagEl = document.getElementById("mapFairyRouteTag");
    if (tagEl) {
      tagEl.textContent = `🎉 목적지 도착! (${place.name})`;
    }
    updateMapTurnByTurnHud();
    renderFairyNavSheet();
    if (!wasArrived) {
      showToast(`🎉 목적지 ${place.name}에 도착했습니다! 즐거운 카공 되세요!`);
      speakFairyInstruction(`${place.name}에 도착했습니다! 즐거운 카공 시간 보내세요.`);
    }
    return;
  }

  // 아직 이동 중이면 내 위치에서 가장 가까운 진행 구간(출발 ~ 마지막 직전 구간) 자동 매칭
  currentFairyNavSession.hasArrived = false;
  let bestStepIdx = 0;
  let minStepDist = Infinity;
  for (let i = 0; i < Math.max(1, steps.length - 1); i++) {
    const c = steps[i].coord;
    if (!c) continue;
    const d = getDistanceMeters(lat, lng, c[0], c[1]);
    if (d < minStepDist) {
      minStepDist = d;
      bestStepIdx = i;
    }
  }
  if (
    currentFairyNavSession.hasMovedFromStart &&
    minStepDist <= 18 &&
    bestStepIdx + 1 < steps.length - 1
  ) {
    bestStepIdx += 1;
  }

  const prevStepIdx = currentFairyNavSession.stepIndex;
  currentFairyNavSession.stepIndex = bestStepIdx;

  // 내 현재 위치에서 목적지까지 실시간 경로선 갱신
  updateLiveRoutePolylines(lat, lng, bestStepIdx);

  const tagEl = document.getElementById("mapFairyRouteTag");
  if (tagEl) {
    tagEl.textContent = `🛰️ 내 위치 추적 중 · 남은 거리 ${distToDest}m`;
  }

  updateMapTurnByTurnHud();
  if (prevStepIdx !== bestStepIdx) {
    renderFairyNavSheet();
  }
}

function startLiveNavGpsTracking(recenterOnFix = false) {
  stopLiveNavGpsTracking();
  if (typeof navigator === "undefined" || !navigator.geolocation) return;

  // 이미 확보된 내 위치가 있고 캠퍼스 반경 이내이면 출발 위치 동기화 (단, 시작 직후 도착 오작동 방지)
  if (state.userGpsCoord && state.userGpsCoord.lat && currentFairyNavSession) {
    const place = currentFairyNavSession.route.place;
    const d = getDistanceMeters(
      state.userGpsCoord.lat,
      state.userGpsCoord.lng,
      place.lat,
      place.lng
    );
    if (d <= 3500) {
      updateFairyNavLivePosition(
        state.userGpsCoord.lat,
        state.userGpsCoord.lng,
        state.userGpsCoord.accuracy || 25,
        recenterOnFix,
        false
      );
    }
  }

  try {
    navGpsWatchId = navigator.geolocation.watchPosition(
      (pos) => {
        updateFairyNavLivePosition(
          pos.coords.latitude,
          pos.coords.longitude,
          pos.coords.accuracy || 25,
          false,
          false
        );
      },
      () => {},
      {
        enableHighAccuracy: true,
        maximumAge: 2000,
        timeout: 10000,
      }
    );
  } catch (_e) {}
}

function updateMapTurnByTurnHud() {
  const hudEl = document.getElementById("mapTurnByTurnHud");
  if (!hudEl) return;

  if (!currentFairyNavSession) {
    hudEl.classList.add("hidden");
    hudEl.innerHTML = "";
    return;
  }

  const { route, stepIndex, remainingDistMeters, hasArrived } = currentFairyNavSession;
  const curStep = route.steps[stepIndex] || route.steps[0];
  const nextStep = route.steps[stepIndex + 1] || null;
  const distBadgeText = hasArrived
    ? "도착"
    : curStep.distanceMeters > 0
    ? `${curStep.distanceMeters}m`
    : `${remainingDistMeters || route.distanceMeters}m`;
  const liveDistText =
    typeof remainingDistMeters === "number"
      ? `남은 거리 ${remainingDistMeters}m`
      : `도보 ${route.durationMin}분`;

  hudEl.innerHTML = `
    <div class="tbt-hud-main-row">
      <div class="tbt-turn-icon-box" aria-hidden="true">
        ${getTurnIconSvg(curStep.turnType)}
        <span class="tbt-turn-dist">${distBadgeText}</span>
      </div>
      <div class="tbt-instruction-col">
        <div class="tbt-step-meta-row">
          <span class="tbt-step-pill">${curStep.badge} (${stepIndex + 1}/${route.steps.length})</span>
          <span class="tbt-eta-text">🛰️ ${liveDistText} · ${route.arrivalTimeLabel}</span>
        </div>
        <div class="tbt-primary-text">${curStep.instruction}</div>
      </div>
      <button type="button" class="tbt-close-x-btn" id="btnHudCloseNav" aria-label="길안내 종료">✕</button>
    </div>
    ${
      nextStep && !hasArrived
        ? `<div class="tbt-hud-sub-row">
            <span class="tbt-next-label">다음 안내</span>
            <span class="tbt-next-desc">${nextStep.turnLabel} · ${nextStep.subText}</span>
          </div>`
        : `<div class="tbt-hud-sub-row is-arrived">
            <span class="tbt-next-label">안내 완료</span>
            <span class="tbt-next-desc">목적지 ${route.place.name}에 도착했습니다! 🎉</span>
          </div>`
    }
  `;
  hudEl.classList.remove("hidden");

  const btnHudClose = document.getElementById("btnHudCloseNav");
  if (btnHudClose) {
    btnHudClose.addEventListener("click", (e) => {
      e.stopPropagation();
      stopFairyNavigation(true);
    });
  }
}

function stopFairyNavigation(returnToDetail = true) {
  stopLiveNavGpsTracking();
  if (fairyAnimFrameId) {
    cancelAnimationFrame(fairyAnimFrameId);
    fairyAnimFrameId = null;
  }
  if (typeof window !== "undefined" && "speechSynthesis" in window) {
    try {
      window.speechSynthesis.cancel();
    } catch (_e) {}
  }
  if (fairyRouteLayerGroup && leafletMap) {
    leafletMap.removeLayer(fairyRouteLayerGroup);
    fairyRouteLayerGroup = null;
  }
  fairyFlyingMarker = null;
  fairyWalkedPolyline = null;
  fairyActiveGlowPolyline = null;
  fairyActiveMainPolyline = null;
  fairyActiveDashPolyline = null;

  const hudEl = document.getElementById("mapTurnByTurnHud");
  if (hudEl) {
    hudEl.classList.add("hidden");
  }

  const sheet = document.getElementById("mainBottomSheet");
  const navView = document.getElementById("sheetFairyNavView");
  const detailView = document.getElementById("sheetDetailView");
  const listView = document.getElementById("sheetListView");
  document.body.classList.remove("is-fairy-nav-mode");
  if (listView) listView.classList.remove("hidden");
  if (sheet) sheet.classList.remove("is-fairy-nav");
  if (navView) navView.classList.add("hidden");
  if (returnToDetail && detailView && state.selectedPlaceId !== null) {
    if (sheet) sheet.classList.remove("hidden");
    detailView.classList.remove("hidden");
  }
  currentFairyNavSession = null;
  renderMapView(getSortedDisplayPlaces(getEffectiveReferenceDate()));
  if (leafletMap) {
    setTimeout(() => leafletMap.invalidateSize(), 60);
  }
}

function animateFairyAlongRoute(coords, onComplete) {
  if (!fairyFlyingMarker || !coords || coords.length < 2) return;
  if (fairyAnimFrameId) {
    cancelAnimationFrame(fairyAnimFrameId);
    fairyAnimFrameId = null;
  }

  // 세그먼트별 누적 거리 계산
  const segLengths = [];
  let totalLen = 0;
  for (let i = 0; i < coords.length - 1; i++) {
    const d = Math.hypot(
      coords[i + 1][0] - coords[i][0],
      coords[i + 1][1] - coords[i][1]
    );
    segLengths.push(d);
    totalLen += d;
  }
  if (totalLen === 0) return;

  const durationMs = 3600;
  const startTime = performance.now();

  function stepFrame(now) {
    const elapsed = now - startTime;
    const progress = Math.min(1, elapsed / durationMs);
    const eased =
      progress < 0.5
        ? 4 * progress * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 3) / 2;

    const targetDist = totalLen * eased;
    let acc = 0;
    let lat = coords[0][0];
    let lng = coords[0][1];

    for (let i = 0; i < segLengths.length; i++) {
      if (acc + segLengths[i] >= targetDist) {
        const segRatio =
          segLengths[i] > 0 ? (targetDist - acc) / segLengths[i] : 0;
        lat = coords[i][0] + (coords[i + 1][0] - coords[i][0]) * segRatio;
        lng = coords[i][1] + (coords[i + 1][1] - coords[i][1]) * segRatio;
        break;
      }
      acc += segLengths[i];
    }

    if (fairyFlyingMarker) {
      fairyFlyingMarker.setLatLng([lat, lng]);
    }

    const tagEl = document.getElementById("mapFairyRouteTag");
    if (tagEl && currentFairyNavSession) {
      const steps = currentFairyNavSession.route.steps;
      const idx = Math.min(
        steps.length - 1,
        Math.floor(progress * steps.length)
      );
      tagEl.textContent = steps[idx].shortTag;
    }

    if (progress < 1) {
      fairyAnimFrameId = requestAnimationFrame(stepFrame);
    } else {
      fairyAnimFrameId = null;
      if (typeof onComplete === "function") onComplete();
    }
  }

  fairyAnimFrameId = requestAnimationFrame(stepFrame);
}

function drawFairyRouteOnMap(routeData) {
  initLeafletMapIfNeeded();
  if (!leafletMap) return;

  // 길안내 중에는 기존 기준점/대기 제발요 마커를 숨겨 내 위치 추적 제발요 1마리만 선명하게 표시
  if (anchorMarker) {
    leafletMap.removeLayer(anchorMarker);
    anchorMarker = null;
  }
  if (userGpsMarker) {
    leafletMap.removeLayer(userGpsMarker);
    userGpsMarker = null;
  }

  if (fairyRouteLayerGroup) {
    leafletMap.removeLayer(fairyRouteLayerGroup);
  }
  fairyRouteLayerGroup = L.layerGroup().addTo(leafletMap);

  const initialFairyCoord =
    currentFairyNavSession && currentFairyNavSession.liveUserCoord
      ? currentFairyNavSession.liveUserCoord
      : routeData.coords[0];

  // 0. 이미 지나온 구간 표시용 점선 폴리라인 (내 위치 이동 시 실시간 업데이트)
  fairyWalkedPolyline = L.polyline([routeData.coords[0], initialFairyCoord], {
    color: "#94A3B8",
    weight: 5,
    opacity: 0.65,
    dashArray: "5, 8",
    lineCap: "round",
  }).addTo(fairyRouteLayerGroup);

  // 1. 카카오/네이버 도보 네비 스타일 외곽 블루-바이올렛 글로우 라인 (내 현재 위치 → 목적지)
  fairyActiveGlowPolyline = L.polyline(routeData.coords, {
    color: "#6366F1",
    weight: 13,
    opacity: 0.28,
    lineCap: "round",
    lineJoin: "round",
  }).addTo(fairyRouteLayerGroup);

  // 2. 선명한 메인 경로 라인
  fairyActiveMainPolyline = L.polyline(routeData.coords, {
    color: "#2563EB",
    weight: 6,
    opacity: 0.94,
    lineCap: "round",
    lineJoin: "round",
  }).addTo(fairyRouteLayerGroup);

  // 3. 진행 방향 화이트 점선 애니메이션
  fairyActiveDashPolyline = L.polyline(routeData.coords, {
    color: "#FFFFFF",
    weight: 3,
    opacity: 0.96,
    dashArray: "7, 11",
    className: "fairy-route-animated-line",
  }).addTo(fairyRouteLayerGroup);

  // 4. 출발지(출발) 배지 마커 & 도착지(도착) 배지 마커 표시
  const startCoord = routeData.coords[0];
  const endCoord = routeData.coords[routeData.coords.length - 1];

  const startBadgeIcon = L.divIcon({
    className: "route-endpoint-marker",
    html: `<div class="route-endpoint-pill is-start"><span>출발</span><strong>${escapeHtmlSafe(
      routeData.origin.label
    )}</strong></div>`,
    iconSize: [0, 0],
    iconAnchor: [0, 0],
  });
  L.marker(startCoord, { icon: startBadgeIcon, zIndexOffset: 960 }).addTo(
    fairyRouteLayerGroup
  );

  const endBadgeIcon = L.divIcon({
    className: "route-endpoint-marker",
    html: `<div class="route-endpoint-pill is-end"><span>도착</span><strong>${escapeHtmlSafe(
      routeData.place.name
    )}</strong></div>`,
    iconSize: [0, 0],
    iconAnchor: [0, 0],
  });
  L.marker(endCoord, { icon: endBadgeIcon, zIndexOffset: 970 }).addTo(
    fairyRouteLayerGroup
  );

  // 5. 경유 회전 지점 포인트 원 표시
  routeData.steps.slice(1, -1).forEach((st, idx) => {
    if (!st.coord) return;
    L.circleMarker(st.coord, {
      radius: 5,
      color: "#1D4ED8",
      weight: 2,
      fillColor: "#FFFFFF",
      fillOpacity: 1,
    })
      .bindTooltip(`${idx + 1}. ${st.turnLabel}`, { direction: "top" })
      .addTo(fairyRouteLayerGroup);
  });

  // 6. 내 현재 위치를 실시간으로 추적하며 그 위치에 머무는 제발요 + 실시간 GPS 블루닷 파동 링
  const remMeters =
    currentFairyNavSession && typeof currentFairyNavSession.remainingDistMeters === "number"
      ? currentFairyNavSession.remainingDistMeters
      : routeData.distanceMeters;
  const initialTagText =
    currentFairyNavSession && currentFairyNavSession.hasArrived
      ? `🎉 목적지 도착! (${routeData.place.name})`
      : `🛰️ 내 위치 추적 중 · 남은 거리 ${remMeters}m`;

  const flyIcon = L.divIcon({
    className: "fairy-flying-route-marker",
    html: `
      <div class="fairy-flying-pin-wrap" id="mapFlyingFairyWrap">
        <span class="fairy-flying-speech-tag" id="mapFairyRouteTag">${initialTagText}</span>
        <div class="fairy-gemini-halo">
          <img
            src="./assets/fairy/fairy-fly.webp?v=20261102_6"
            alt="길안내 제발요"
            class="fairy-flying-pin-img fairy-float"
            width="62"
            height="58"
          />
        </div>
        <span class="nav-user-gps-puck" aria-hidden="true">
          <span class="nav-gps-pulse"></span>
          <span class="nav-gps-core"></span>
        </span>
      </div>
    `,
    iconSize: [0, 0],
    iconAnchor: [0, 0],
  });

  fairyFlyingMarker = L.marker(initialFairyCoord, {
    icon: flyIcon,
    zIndexOffset: 1200,
  }).addTo(fairyRouteLayerGroup);

  fairyFlyingMarker.on("click", (e) => {
    L.DomEvent.stopPropagation(e);
    const wrapEl = document.getElementById("mapFlyingFairyWrap");
    triggerFairySparkleAndHop(wrapEl);
    if (currentFairyNavSession) {
      const curStep =
        currentFairyNavSession.route.steps[currentFairyNavSession.stepIndex];
      speakFairyInstruction(curStep.instruction);
    }
  });

  // 상단 HUD와 하단 길안내 시트 사이의 열린 지도 영역에 내 위치(제발요)와 전체 경로가 모두 넉넉히 들어오도록 카메라 맞춤
  const fitRouteBounds = () => {
    if (!leafletMap) return;
    leafletMap.invalidateSize();
    const allPoints = [...routeData.coords, initialFairyCoord];
    const bounds = L.latLngBounds(allPoints);
    leafletMap.fitBounds(bounds, {
      paddingTopLeft: [64, 244],
      paddingBottomRight: [64, 430],
      maxZoom: 17,
      animate: false,
    });
  };

  fitRouteBounds();
  setTimeout(fitRouteBounds, 300);
}

function selectFairyNavStep(nextIndex) {
  if (!currentFairyNavSession) return;
  const steps = currentFairyNavSession.route.steps;
  if (nextIndex < 0 || nextIndex >= steps.length) return;
  currentFairyNavSession.stepIndex = nextIndex;
  const isLastStep = nextIndex === steps.length - 1;
  currentFairyNavSession.hasArrived = isLastStep;
  const step = steps[nextIndex];
  if (step.coord) {
    currentFairyNavSession.liveUserCoord = step.coord;
    if (isLastStep) {
      currentFairyNavSession.hasMovedFromStart = true;
      currentFairyNavSession.remainingDistMeters = 0;
    } else {
      currentFairyNavSession.remainingDistMeters = Math.round(
        getDistanceMeters(
          step.coord[0],
          step.coord[1],
          currentFairyNavSession.route.place.lat,
          currentFairyNavSession.route.place.lng
        )
      );
    }
    updateLiveRoutePolylines(step.coord[0], step.coord[1], nextIndex);
  }
  if (fairyFlyingMarker && step.coord) {
    fairyFlyingMarker.setLatLng(step.coord);
    const tagEl = document.getElementById("mapFairyRouteTag");
    if (tagEl) {
      tagEl.textContent = isLastStep
        ? `🎉 목적지 도착! (${currentFairyNavSession.route.place.name})`
        : `🛰️ 내 위치 추적 중 · 남은 거리 ${currentFairyNavSession.remainingDistMeters}m`;
    }
  }
  updateMapTurnByTurnHud();
  renderFairyNavSheet();
}

function renderFairyNavSheet() {
  if (!currentFairyNavSession) return;
  const { route, stepIndex, originMode, routeOption } = currentFairyNavSession;
  const { place, origin } = route;
  const curStep = route.steps[stepIndex] || route.steps[0];

  const navView = document.getElementById("sheetFairyNavView");
  const detailView = document.getElementById("sheetDetailView");
  if (!navView) return;

  if (detailView) detailView.classList.add("hidden");
  navView.classList.remove("hidden");

  updateMapTurnByTurnHud();

  const { naverWalkUrl, kakaoWalkUrl } = getDirectExternalWalkLinks(
    origin,
    place
  );

  const stepListHtml = route.steps
    .map((st, idx) => {
      const isCurrent = idx === stepIndex;
      const distBadge = st.distanceMeters > 0 ? `${st.distanceMeters}m` : "도착";
      return `
        <button
          type="button"
          class="nav-step-timeline-item ${isCurrent ? "is-active-step" : ""}"
          data-nav-step-idx="${idx}"
        >
          <span class="nav-step-icon-circle">${getTurnIconSvg(st.turnType)}</span>
          <div class="nav-step-text-col">
            <div class="nav-step-title-row">
              <span class="nav-step-turn-title">${st.badge} · ${st.turnLabel}</span>
              <span class="nav-step-dist-pill">${distBadge}</span>
            </div>
            <p class="nav-step-desc">${st.instruction}</p>
          </div>
        </button>
      `;
    })
    .join("");

  navView.innerHTML = `
    <!-- 카카오맵·네이버지도 도보 길찾기 스타일 상단 요약 헤더 -->
    <div class="fairy-nav-header">
      <div class="fairy-nav-badge-title">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#2563EB" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <polygon points="3 11 22 2 13 21 11 13 3 11"></polygon>
        </svg>
        <span>도보 길찾기 · 제발요 네비게이션</span>
      </div>
      <button type="button" class="fairy-nav-close-btn" id="btnCloseFairyNav" aria-label="길안내 종료하고 상세정보로 돌아가기">
        <span>← 상세정보로</span>
      </button>
    </div>

    <!-- 경로 옵션 탭 (추천경로 / 큰길우선 / 최단거리) + 출발지 전환 -->
    <div class="nav-route-options-bar">
      <div class="nav-route-type-tabs" role="tablist" aria-label="도보 경로 옵션">
        <button type="button" class="nav-route-tab ${routeOption === "recommend" ? "is-active" : ""}" data-route-opt="recommend">추천경로</button>
        <button type="button" class="nav-route-tab ${routeOption === "mainroad" ? "is-active" : ""}" data-route-opt="mainroad">큰길우선</button>
        <button type="button" class="nav-route-tab ${routeOption === "shortest" ? "is-active" : ""}" data-route-opt="shortest">최단거리</button>
      </div>
      <div class="fairy-nav-origin-switch" role="group" aria-label="출발 위치 변경">
        <button
          type="button"
          class="origin-pill-btn ${originMode === "anchor" ? "is-active" : ""}"
          id="btnNavOriginAnchor"
        >
          ${state.anchorCoord.label} 출발
        </button>
        <button
          type="button"
          class="origin-pill-btn ${originMode === "gps" ? "is-active" : ""}"
          id="btnNavOriginGps"
        >
          내 위치 출발
        </button>
      </div>
    </div>

    <!-- 소요 시간 · 도착 예정 시각 · 거리 · 걸음수 · 칼로리 카드 (카카오/네이버 도보 요약 카드) -->
    <div class="fairy-nav-route-summary">
      <div class="fairy-nav-from-to">
        <div class="nav-big-time-row">
          <strong class="nav-big-duration">도보 ${route.durationMin}분</strong>
          <span class="nav-eta-badge">${route.arrivalTimeLabel}</span>
        </div>
        <div class="fairy-nav-route-endpoints">${origin.label} → ${place.name}</div>
        <div class="fairy-nav-route-metrics">
          총 ${route.distanceMeters}m · 약 ${route.stepsCount}걸음 · ${route.calories}kcal · 횡단보도 ${route.crosswalkCount}회
        </div>
      </div>
      <div class="fairy-nav-mascot-wrap fairy-gemini-halo" id="navStageFairyTrigger" title="제발요를 누르면 음성으로 안내해 줘요">
        <img
          src="./assets/fairy/fairy-fly.webp?v=20261102_6"
          alt="길안내 제발요"
          class="fairy-nav-mascot-img fairy-float"
          id="navStageFairyImg"
          width="66"
          height="60"
        />
      </div>
    </div>

    <!-- 현재 구간 컨트롤 & 음성 안내 바 -->
    <div class="fairy-nav-controls-row">
      <button
        type="button"
        class="fairy-step-ctrl-btn"
        id="btnPrevRouteStep"
        ${stepIndex === 0 ? "disabled" : ""}
      >
        <span>◀ 이전 구간</span>
      </button>
      <button
        type="button"
        class="fairy-step-ctrl-btn primary-step-btn"
        id="btnNextRouteStep"
        ${stepIndex >= route.steps.length - 1 ? "disabled" : ""}
      >
        <span>다음 구간 안내 ▶</span>
      </button>
      <button
        type="button"
        class="fairy-step-ctrl-btn"
        id="btnReplayFairyFlight"
      >
        <span>🛰️ 내 위치 추적</span>
      </button>
      <button
        type="button"
        class="fairy-step-ctrl-btn"
        id="btnSpeakFairyStep"
        aria-label="제발요 음성 안내 듣기"
      >
        <span>🔊 음성</span>
      </button>
    </div>

    <!-- 구간별 상세 턴바이턴(Turn-by-Turn) 타임라인 리스트 (누르면 해당 구간으로 이동) -->
    <div class="nav-step-timeline-list" role="list" aria-label="구간별 도보 상세 경로">
      ${stepListHtml}
    </div>

    <!-- 네이버지도 · 카카오맵 실제 길찾기 연동 버튼 -->
    <div class="detail-ext-links" style="margin-top: 10px;">
      <a
        href="${naverWalkUrl}"
        target="_blank"
        rel="noopener noreferrer"
        class="ext-link-btn naver-btn"
        aria-label="네이버 지도에서 매장 위치 및 길찾기 열기"
      >
        <span class="ext-brand-dot naver" aria-hidden="true"></span>
        <span>네이버 지도 길찾기 ↗</span>
      </a>
      <a
        href="${kakaoWalkUrl}"
        target="_blank"
        rel="noopener noreferrer"
        class="ext-link-btn kakao-btn"
        aria-label="카카오맵 도보 길찾기 바로 열기"
      >
        <span class="ext-brand-dot kakao" aria-hidden="true"></span>
        <span>카카오맵 도보 길찾기 ↗</span>
      </a>
    </div>
  `;

  const btnClose = document.getElementById("btnCloseFairyNav");
  if (btnClose) {
    btnClose.addEventListener("click", () => {
      stopFairyNavigation(true);
    });
  }

  navView.querySelectorAll("[data-route-opt]").forEach((tabBtn) => {
    tabBtn.addEventListener("click", () => {
      const nextOpt = tabBtn.dataset.routeOpt || "recommend";
      startFairyNavigation(place, originMode, nextOpt);
    });
  });

  navView.querySelectorAll("[data-nav-step-idx]").forEach((stepBtn) => {
    stepBtn.addEventListener("click", () => {
      const idx = Number(stepBtn.dataset.navStepIdx);
      selectFairyNavStep(idx);
    });
  });

  const btnOriginAnchor = document.getElementById("btnNavOriginAnchor");
  if (btnOriginAnchor) {
    btnOriginAnchor.addEventListener("click", () => {
      startFairyNavigation(place, "anchor", routeOption);
    });
  }

  const btnOriginGps = document.getElementById("btnNavOriginGps");
  if (btnOriginGps) {
    btnOriginGps.addEventListener("click", () => {
      if (state.userGpsCoord && state.userGpsCoord.lat) {
        startFairyNavigation(place, "gps", routeOption);
        return;
      }
      if (!navigator.geolocation) {
        showToast("이 브라우저에서는 GPS 위치 기능을 지원하지 않아요.");
        return;
      }
      showToast("내 현재 위치(GPS)를 확인해 도보 경로를 다시 찾고 있어요...");
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          state.userGpsCoord = {
            lat: pos.coords.latitude,
            lng: pos.coords.longitude,
            label: "내 위치",
          };
          startFairyNavigation(place, "gps", routeOption);
        },
        () => {
          showToast(
            `위치 권한이 꺼져 있어 ${state.anchorCoord.label} 출발 기준으로 안내할게요!`
          );
          startFairyNavigation(place, "anchor", routeOption);
        },
        { enableHighAccuracy: false, timeout: 8000, maximumAge: 120000 }
      );
    });
  }

  const btnPrev = document.getElementById("btnPrevRouteStep");
  if (btnPrev) {
    btnPrev.addEventListener("click", () => {
      selectFairyNavStep(currentFairyNavSession.stepIndex - 1);
    });
  }

  const btnNext = document.getElementById("btnNextRouteStep");
  if (btnNext) {
    btnNext.addEventListener("click", () => {
      selectFairyNavStep(currentFairyNavSession.stepIndex + 1);
    });
  }

  const btnReplay = document.getElementById("btnReplayFairyFlight");
  if (btnReplay) {
    btnReplay.addEventListener("click", () => {
      const fairyImg = document.getElementById("navStageFairyImg");
      triggerFairySparkleAndHop(fairyImg);
      if (state.userGpsCoord && state.userGpsCoord.lat) {
        updateFairyNavLivePosition(
          state.userGpsCoord.lat,
          state.userGpsCoord.lng,
          state.userGpsCoord.accuracy || 20,
          true,
          false
        );
        showToast("🛰️ 현재 내 위치로 제발요를 이동하고 실시간 위치 추적을 이어갑니다!");
      } else if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          (pos) => {
            updateFairyNavLivePosition(
              pos.coords.latitude,
              pos.coords.longitude,
              pos.coords.accuracy || 20,
              true,
              false
            );
            showToast("🛰️ 내 현재 위치를 파악해 제발요가 내 위치에서 안내합니다!");
          },
          () => {
            if (fairyFlyingMarker && route.coords[0]) {
              fairyFlyingMarker.setLatLng(route.coords[0]);
            }
            showToast(`📍 위치 신호가 약해 출발지(${origin.label}) 기준으로 안내합니다.`);
          },
          { enableHighAccuracy: false, timeout: 8000, maximumAge: 120000 }
        );
      }
    });
  }

  const btnSpeak = document.getElementById("btnSpeakFairyStep");
  const navFairyTrigger = document.getElementById("navStageFairyTrigger");
  const handleSpeak = () => {
    const fairyImg = document.getElementById("navStageFairyImg");
    triggerFairySparkleAndHop(fairyImg);
    speakFairyInstruction(curStep.instruction);
  };
  if (btnSpeak) btnSpeak.addEventListener("click", handleSpeak);
  if (navFairyTrigger) navFairyTrigger.addEventListener("click", handleSpeak);
}

async function startFairyNavigation(
  place,
  originMode = "anchor",
  routeOption = "recommend"
) {
  // 만약 카페가 다른 캠퍼스에 속해 있다면 해당 캠퍼스의 기준점(정문 등)을 출발지로 자동 매칭
  const effectiveCampusAnchor =
    place.campus !== state.campus && CAMPUS_ANCHORS[place.campus]
      ? CAMPUS_ANCHORS[place.campus][0]
      : state.anchorCoord;

  // 내 위치(GPS)가 목적지 반경 3km 이내에 있으면 내 위치를 출발지로 사용
  const hasValidNearbyGps =
    state.userGpsCoord &&
    state.userGpsCoord.lat &&
    getDistanceMeters(
      state.userGpsCoord.lat,
      state.userGpsCoord.lng,
      place.lat,
      place.lng
    ) <= 3000;

  const origin =
    originMode === "gps" && hasValidNearbyGps
      ? {
          lat: state.userGpsCoord.lat,
          lng: state.userGpsCoord.lng,
          label: "내 위치",
        }
      : effectiveCampusAnchor;

  // 제발요 길안내 시작 시 지도 탭으로 전환하되 closeDetail=false로 상세/네비 시트가 절대 닫히지 않게 유지!
  document.body.classList.add("is-fairy-nav-mode");
  setMainViewMode("map", "fairy_nav", false);
  const sheet = document.getElementById("mainBottomSheet");
  const detailView = document.getElementById("sheetDetailView");
  const navView = document.getElementById("sheetFairyNavView");
  if (sheet) {
    sheet.classList.remove("hidden");
    sheet.classList.add("is-fairy-nav");
  }
  if (detailView) detailView.classList.add("hidden");
  if (navView) navView.classList.remove("hidden");

  trackEvent("start_fairy_navigation", {
    place_id: place.id,
    place_name: place.name,
    origin_mode: originMode,
    route_option: routeOption,
  });

  // 0ms 즉시 렌더링: 스마트 캠퍼스 도보 경로로 HUD·경로선·내 위치 제발요·바텀시트를 딜레이 없이 즉시 표시!
  const instantRoute = generateSmartCampusFootpath(origin, place, routeOption);
  const startCoord = [origin.lat, origin.lng];
  currentFairyNavSession = {
    route: instantRoute,
    stepIndex: 0,
    originMode,
    routeOption,
    startedAt: Date.now(),
    startCoord,
    hasMovedFromStart: false,
    hasArrived: false,
    remainingDistMeters: instantRoute.distanceMeters,
    liveUserCoord: startCoord,
  };

  drawFairyRouteOnMap(instantRoute);
  renderFairyNavSheet();
  startLiveNavGpsTracking(false);
  showToast(
    `🛰️ ${origin.label} → ${place.name} 제발요 실시간 위치 추적 길안내를 시작합니다!`
  );

  // 백그라운드에서 OSRM 정밀 보행 경로가 응답하면 끊김 없이 경로선만 정밀 업데이트
  const refinedRoute = await buildFairyWalkingRoute(origin, place, routeOption);
  if (
    currentFairyNavSession &&
    currentFairyNavSession.route.place.id === place.id &&
    currentFairyNavSession.routeOption === routeOption &&
    refinedRoute.coords.length > instantRoute.coords.length
  ) {
    currentFairyNavSession.route = refinedRoute;
    drawFairyRouteOnMap(refinedRoute);
    renderFairyNavSheet();
    if (state.userGpsCoord && state.userGpsCoord.lat) {
      updateFairyNavLivePosition(
        state.userGpsCoord.lat,
        state.userGpsCoord.lng,
        state.userGpsCoord.accuracy || 20,
        false,
        currentFairyNavSession.hasMovedFromStart
      );
    }
  }
}

// 17. 5-2절: 지도 렌더링 (평소 줌(15 이하)에는 제미나이·화이트 불빛 오브, 줌인(>=16) 또는 선택 시 카페 이름 표시)
const MAP_LABEL_ZOOM_THRESHOLD = 16;

function syncMapZoomClass() {
  const mapStage = document.getElementById("mapStage");
  if (!mapStage || !leafletMap) return;
  const currentZoom = leafletMap.getZoom();
  mapStage.classList.toggle("is-zoomed-in", currentZoom >= MAP_LABEL_ZOOM_THRESHOLD);
}

function initLeafletMapIfNeeded() {
  if (leafletMap || typeof window.L === "undefined") return;

  leafletMap = L.map("leafletMap", {
    zoomControl: false,
  }).setView([state.anchorCoord.lat, state.anchorCoord.lng], 15);

  // 채도 낮은 밝은 지도 (밤 시간대에는 body.is-night-mode 필터로 어두워짐)
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    maxZoom: 19,
    attribution:
      '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
  }).addTo(leafletMap);

  placeMarkersLayer = L.layerGroup().addTo(leafletMap);

  leafletMap.on("zoomend", () => {
    syncMapZoomClass();
  });

  leafletMap.on("click", () => {
    if (state.selectedPlaceId !== null && !currentFairyNavSession) {
      closePlaceDetail();
    }
  });

  syncMapZoomClass();
}

function highlightSelectedMarkerOnMap(selectedId) {
  markerElementsById.forEach((wrapEl, id) => {
    wrapEl.classList.toggle("is-selected", id === selectedId);
  });
  document.querySelectorAll(".place-card").forEach((cardEl) => {
    const cid = Number(cardEl.dataset.placeId);
    cardEl.classList.toggle("is-selected-card", cid === selectedId);
  });
}

function renderMapView(displayedPlaces) {
  initLeafletMapIfNeeded();
  if (!leafletMap) return;
  syncMapZoomClass();

  if (radiusCircle) {
    leafletMap.removeLayer(radiusCircle);
    radiusCircle = null;
  }
  if (anchorMarker) {
    leafletMap.removeLayer(anchorMarker);
    anchorMarker = null;
  }
  if (userGpsMarker) {
    leafletMap.removeLayer(userGpsMarker);
    userGpsMarker = null;
  }
  if (gpsAccuracyCircle) {
    leafletMap.removeLayer(gpsAccuracyCircle);
    gpsAccuracyCircle = null;
  }
  placeMarkersLayer.clearLayers();
  markerElementsById.clear();

  // 반경 원: 은은한 제미나이 블루·바이올렛 점선
  if (state.radiusMeters > 0) {
    radiusCircle = L.circle([state.anchorCoord.lat, state.anchorCoord.lng], {
      radius: state.radiusMeters,
      color: "#6366F1",
      weight: 1.4,
      opacity: 0.35,
      dashArray: "5, 5",
      fillColor: "#6366F1",
      fillOpacity: 0.04,
    }).addTo(leafletMap);
  }

  // 길안내 중이 아닐 때만 기본 기준점 제발요 및 내 위치 제발요 마커 표시
  if (!currentFairyNavSession) {
    const isGpsAnchor = state.anchorKey === "gps";
    const anchorBadgeHtml = isGpsAnchor
      ? `<span class="fairy-gps-live-badge"><span class="gps-pulse-dot"></span>내 위치 제발요</span>`
      : `<span class="fairy-anchor-label-badge">${state.anchorCoord.label}</span>`;

    const anchorIcon = L.divIcon({
      className: "fairy-anchor-marker",
      html: `
        <div class="fairy-anchor-ring fairy-float ${isGpsAnchor ? "is-gps-fairy" : ""}" id="mapFairyAnchorRing" title="${state.anchorCoord.label} 기준점 (눌러서 중심 맞추기)">
          ${anchorBadgeHtml}
          <div class="fairy-anchor-inner">
            <img src="./assets/fairy/fairy-wave.webp?v=20261102_6" alt="${state.anchorCoord.label} 제발요" width="66" height="70" />
          </div>
        </div>
      `,
      iconSize: [80, 92],
      iconAnchor: [40, 48],
    });

    anchorMarker = L.marker([state.anchorCoord.lat, state.anchorCoord.lng], {
      icon: anchorIcon,
      zIndexOffset: isGpsAnchor ? 920 : 150,
    }).addTo(leafletMap);

    anchorMarker.on("click", (e) => {
      L.DomEvent.stopPropagation(e);
      const ringEl = document.getElementById("mapFairyAnchorRing");
      triggerFairySparkleAndHop(ringEl);
      if (leafletMap) {
        leafletMap.panTo([state.anchorCoord.lat, state.anchorCoord.lng], {
          animate: true,
        });
      }
      const cheerMsg = cycleFairyCheerMessage(ringEl);
      showToast(`${state.anchorCoord.label} 제발요: "${cheerMsg}"`);
    });

    // 만약 내 위치(GPS)가 파악되어 있는데 현재 선택된 기준점이 정문/후문 등 다른 곳이라면, 내 위치에도 제발요를 함께 띄워줌
    if (state.userGpsCoord && state.anchorKey !== "gps") {
      const gpsFairyIcon = L.divIcon({
        className: "fairy-anchor-marker",
        html: `
          <div class="fairy-anchor-ring fairy-float is-gps-fairy" id="mapUserGpsFairyRing" title="내 현재 위치 (누르면 내 위치 기준으로 전환)">
            <span class="fairy-gps-live-badge"><span class="gps-pulse-dot"></span>내 위치</span>
            <div class="fairy-anchor-inner">
              <img src="./assets/fairy/fairy-fly.webp?v=20261102_6" alt="내 현재 위치 제발요" width="60" height="56" />
            </div>
          </div>
        `,
        iconSize: [74, 84],
        iconAnchor: [37, 42],
      });

      userGpsMarker = L.marker([state.userGpsCoord.lat, state.userGpsCoord.lng], {
        icon: gpsFairyIcon,
        zIndexOffset: 900,
      }).addTo(leafletMap);

      userGpsMarker.on("click", (e) => {
        L.DomEvent.stopPropagation(e);
        state.anchorKey = "gps";
        state.anchorCoord = {
          lat: state.userGpsCoord.lat,
          lng: state.userGpsCoord.lng,
          label: "내 위치",
        };
        renderAll(true);
        showToast("🧚 내 현재 위치를 기준으로 주변 카페 거리를 다시 계산했어요!");
      });
    }
  }

  // 내 위치(GPS) 반경 오차 원 표시
  const activeGps =
    state.anchorKey === "gps" ? state.anchorCoord : state.userGpsCoord;
  if (activeGps && activeGps.lat && activeGps.lng) {
    gpsAccuracyCircle = L.circle([activeGps.lat, activeGps.lng], {
      radius: Math.min(Math.max(activeGps.accuracy || 35, 18), 90),
      color: "#3B82F6",
      weight: 1.5,
      opacity: 0.55,
      fillColor: "#60A5FA",
      fillOpacity: 0.14,
    }).addTo(leafletMap);
  }

  const cupSvg = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 8h1a4 4 0 1 1 0 8h-1"></path><path d="M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z"></path></svg>`;

  // 인접 건물·동일 상가 내 카페들의 이름 캡슐이 줌인 시 서로 가리지 않도록 미세 수직 오프셋 계산
  const placedLabelBoxes = [];
  const labelOffsetsById = new Map();
  displayedPlaces.forEach((p) => {
    let offsetY = 0;
    const candidateOffsets = [0, -18, 18, -34, 34];
    for (let i = 0; i < candidateOffsets.length; i++) {
      const candY = candidateOffsets[i];
      const effLat = p.lat - candY * 0.000011;
      const hasCollision = placedLabelBoxes.some(
        (box) =>
          Math.abs(effLat - box.effLat) < 0.00018 &&
          Math.abs(p.lng - box.lng) < 0.00072
      );
      if (!hasCollision) {
        offsetY = candY;
        break;
      }
    }
    placedLabelBoxes.push({
      effLat: p.lat - offsetY * 0.000011,
      lng: p.lng,
    });
    labelOffsetsById.set(p.id, offsetY);
  });

  displayedPlaces.forEach((place) => {
    const st = place.businessStatus;
    const isSelected = place.id === state.selectedPlaceId;
    const isClosedPin = !st.isOpen;
    const isClosingSoon = st.state === "closing_soon";
    const offsetY = labelOffsetsById.get(place.id) || 0;
    const pinOffsetStyle =
      offsetY !== 0 && !isSelected
        ? `style="transform: translateY(${offsetY}px);"`
        : "";

    const markerHtml = `
      <div class="cafe-map-pin-wrap ${isSelected ? "is-selected" : ""}" data-marker-id="${place.id}" title="${place.name}">
        <div class="cafe-light-orb ${isClosedPin ? "orb-closed" : ""} ${isClosingSoon ? "orb-closing" : ""}" aria-hidden="true">
          <span class="orb-halo"></span>
          <span class="orb-core"></span>
        </div>
        <div class="cafe-map-pin ${isClosedPin ? "pin-closed" : ""}" ${pinOffsetStyle}>
          ${cupSvg}
          <span class="cafe-pin-name-text">${place.name}</span>
          ${isClosingSoon ? `<span class="pin-closing-dot" title="곧 마감"></span>` : ""}
        </div>
      </div>
    `;

    const icon = L.divIcon({
      className: "custom-cafe-pin-container",
      html: markerHtml,
      iconSize: [0, 0],
      iconAnchor: [0, 0],
    });

    const marker = L.marker([place.lat, place.lng], {
      icon,
      zIndexOffset: isSelected ? 800 : st.isOpen ? 400 : 100,
    }).addTo(placeMarkersLayer);

    marker.on("add", () => {
      const el = marker.getElement();
      if (el) {
        const wrap = el.querySelector(".cafe-map-pin-wrap");
        if (wrap) markerElementsById.set(place.id, wrap);
      }
    });

    marker.on("click", (e) => {
      L.DomEvent.stopPropagation(e);
      trackEvent("place_click", {
        place_id: place.id,
        place_name: place.name,
        source: "map_marker",
      });
      openPlaceDetail(place.id, true);
    });
  });
}

// 18. 아래 패널 하나로 해결 (내리면 지도 snap-peek / 중간 snap-half / 올리면 목록 snap-full) & 당겨서 새로고침
function setSheetSnapMode(snapMode = "half") {
  const listStage = document.getElementById("listStage");
  const snapLabel = document.getElementById("sheetSnapBtnLabel");
  if (!listStage) return;

  const validSnap =
    snapMode === "peek" || snapMode === "full" ? snapMode : "half";
  state.sheetState = validSnap;
  state.activeMainView = validSnap === "full" ? "list" : "map";

  listStage.classList.remove("snap-peek", "snap-half", "snap-full");
  listStage.classList.add(`snap-${validSnap}`);

  if (snapLabel) {
    snapLabel.textContent =
      validSnap === "full"
        ? "내리면 지도 ▼"
        : validSnap === "peek"
        ? "올리면 목록 ▲"
        : "목록 전체보기 ▲";
  }

  if (leafletMap) {
    setTimeout(() => {
      leafletMap.invalidateSize();
    }, 240);
  }
}

function setMainViewMode(nextMode, source = "tab", closeDetail = true) {
  const mode = nextMode === "list" ? "list" : "map";
  state.activeMainView = mode;

  if (closeDetail && state.selectedPlaceId !== null) {
    closePlaceDetail();
  }

  if (source === "fairy_nav") {
    setSheetSnapMode("peek");
  } else if (mode === "list") {
    setSheetSnapMode(source === "ai_prompt_recommend" ? "half" : "full");
  } else {
    setSheetSnapMode("peek");
  }

  trackEvent("view_toggle", {
    view_mode: mode,
    source,
  });
}

function setBottomSheetState(nextState) {
  setSheetSnapMode(nextState);
}

function initHorizontalSwipeNavigation() {
  const listStage = document.getElementById("listStage");
  const dragHeader = document.getElementById("unifiedSheetDragHeader");
  const btnSnap = document.getElementById("btnToggleSheetSnap");
  const scrollBody = document.getElementById("sheetScrollBody");
  const pullBanner = document.getElementById("pullRefreshBanner");

  // 기본 진입 시 지도와 상단 추천/목록이 함께 보이는 반열림(snap-half)으로 시작
  setSheetSnapMode("half");

  if (btnSnap) {
    btnSnap.addEventListener("click", (e) => {
      e.stopPropagation();
      const cur = state.sheetState || "half";
      if (cur === "full") {
        setSheetSnapMode("peek");
      } else if (cur === "half") {
        setSheetSnapMode("full");
      } else {
        setSheetSnapMode("half");
      }
    });
  }

  if (dragHeader && listStage) {
    let startY = null;
    dragHeader.addEventListener("click", () => {
      const cur = state.sheetState || "half";
      if (cur === "peek") {
        setSheetSnapMode("half");
      } else if (cur === "half") {
        setSheetSnapMode("full");
      } else {
        setSheetSnapMode("peek");
      }
    });

    dragHeader.addEventListener(
      "touchstart",
      (e) => {
        if (e.touches.length === 1) {
          startY = e.touches[0].clientY;
        }
      },
      { passive: true }
    );

    dragHeader.addEventListener(
      "touchend",
      (e) => {
        if (startY === null) return;
        const touch = e.changedTouches[0];
        const dy = touch ? touch.clientY - startY : 0;
        startY = null;
        const cur = state.sheetState || "half";
        if (dy < -32) {
          // 위로 올리면 목록 확대
          setSheetSnapMode(cur === "peek" ? "half" : "full");
        } else if (dy > 32) {
          // 아래로 내리면 지도 확대
          setSheetSnapMode(cur === "full" ? "half" : "peek");
        }
      },
      { passive: true }
    );
  }

  // 목록 맨 위에서 아래로 당겨서 새로고침 (Pull-to-Refresh)
  if (scrollBody) {
    let pullStartY = null;
    scrollBody.addEventListener(
      "touchstart",
      (e) => {
        if (scrollBody.scrollTop <= 0 && e.touches.length === 1) {
          pullStartY = e.touches[0].clientY;
        } else {
          pullStartY = null;
        }
      },
      { passive: true }
    );

    scrollBody.addEventListener(
      "touchend",
      (e) => {
        if (pullStartY === null) return;
        const touch = e.changedTouches[0];
        const dy = touch ? touch.clientY - pullStartY : 0;
        pullStartY = null;
        if (scrollBody.scrollTop <= 0 && dy > 60) {
          if (pullBanner) pullBanner.classList.remove("hidden");
          refreshAllLiveBusinessInfo();
          setTimeout(() => {
            if (pullBanner) pullBanner.classList.add("hidden");
          }, 900);
        }
      },
      { passive: true }
    );
  }

  // 첫 방문 때만 닫을 수 있는 작은 알림 1회 표시
  const firstVisitToast = document.getElementById("firstVisitMiniToast");
  const btnDismissFirst = document.getElementById("btnDismissFirstVisitToast");
  const btnFirstOpenOffer = document.getElementById("btnFirstVisitOpenOffer");
  const FIRST_VISIT_KEY = "khu_first_visit_toast_dismissed_v1";

  try {
    if (firstVisitToast && localStorage.getItem(FIRST_VISIT_KEY) !== "1") {
      firstVisitToast.classList.remove("hidden");
    }
  } catch (_e) {}

  if (btnDismissFirst && firstVisitToast) {
    btnDismissFirst.addEventListener("click", (e) => {
      e.stopPropagation();
      firstVisitToast.classList.add("hidden");
      try {
        localStorage.setItem(FIRST_VISIT_KEY, "1");
      } catch (_e) {}
    });
  }
  if (btnFirstOpenOffer && firstVisitToast) {
    btnFirstOpenOffer.addEventListener("click", () => {
      firstVisitToast.classList.add("hidden");
      try {
        localStorage.setItem(FIRST_VISIT_KEY, "1");
      } catch (_e) {}
      const offerModal = document.getElementById("geminiOfferModal");
      if (offerModal) offerModal.classList.remove("hidden");
    });
  }
}

function initBottomSheetDrag() {
  const dragZone = document.getElementById("sheetDragZone");
  const sheet = document.getElementById("mainBottomSheet");
  if (!dragZone || !sheet) return;

  let startY = null;

  dragZone.addEventListener("click", () => {
    closePlaceDetail();
  });

  dragZone.addEventListener(
    "touchstart",
    (e) => {
      if (e.touches.length === 1) startY = e.touches[0].clientY;
    },
    { passive: true }
  );
  dragZone.addEventListener("touchend", (e) => {
    if (startY === null) return;
    const touch = e.changedTouches[0];
    const deltaY = touch ? touch.clientY - startY : 0;
    startY = null;
    if (deltaY > 38) {
      closePlaceDetail();
    }
  });

  dragZone.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      closePlaceDetail();
    }
  });
}

// 19. 내 위치(GPS) 요청 및 로딩 표시 (fairy-fly.webp)
function setLoadingState(visible, message = "자리 알아보는 중…") {
  const pill = document.getElementById("loadingIndicator");
  const textEl = document.getElementById("loadingText");
  if (!pill) return;
  if (textEl) textEl.textContent = message;
  pill.classList.toggle("hidden", !visible);
}

function applyGpsPosition(pos, recenter = true, silent = false) {
  setLoadingState(false);
  const lat = pos.coords.latitude;
  const lng = pos.coords.longitude;
  const accuracy = pos.coords.accuracy || 30;

  state.userGpsCoord = {
    lat,
    lng,
    accuracy,
    label: "내 위치",
  };

  // 내 위치가 서울캠과 국제캠 중 어디에 더 가까운지 자동 판별하여 캠퍼스 동기화 (반경 8km 이내일 때)
  const distSeoul = getDistanceMeters(
    lat,
    lng,
    CAMPUS_ANCHORS.seoul[0].lat,
    CAMPUS_ANCHORS.seoul[0].lng
  );
  const distGlobal = getDistanceMeters(
    lat,
    lng,
    CAMPUS_ANCHORS.global[0].lat,
    CAMPUS_ANCHORS.global[0].lng
  );
  if (distGlobal < distSeoul && distGlobal <= 8000 && state.campus !== "global") {
    state.campus = "global";
  } else if (distSeoul < distGlobal && distSeoul <= 8000 && state.campus !== "seoul") {
    state.campus = "seoul";
  }

  state.anchorKey = "gps";
  state.anchorCoord = {
    lat,
    lng,
    accuracy,
    label: "내 위치",
  };

  // 만약 내 위치가 캠퍼스에서 1km보다 멀어도 카페 목록이 0개로 비지 않도록 전체 반경(0)으로 자동 유지
  const nearestAnchorDist = Math.min(distSeoul, distGlobal);
  if (state.radiusMeters > 0 && nearestAnchorDist > state.radiusMeters) {
    state.radiusMeters = 0;
  }

  const btnMyLoc = document.getElementById("btnMapMyLocation");
  if (btnMyLoc) {
    btnMyLoc.classList.add("is-gps-active");
  }

  renderAll(recenter);
  if (!silent) {
    showToast("🧚 내 현재 위치를 파악해 제발요가 내 위치로 날아왔어요!");
  }
}

function startContinuousGpsWatch() {
  if (!navigator.geolocation || gpsWatchId !== null) return;
  try {
    gpsWatchId = navigator.geolocation.watchPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const prev = state.userGpsCoord;
        state.userGpsCoord = {
          lat,
          lng,
          accuracy: pos.coords.accuracy || 30,
          label: "내 위치",
        };
        if (state.anchorKey === "gps") {
          state.anchorCoord = { ...state.userGpsCoord };
        }
        // 15m 이상 이동했을 때만 지도 마커/거리 갱신
        if (!prev || getDistanceMeters(prev.lat, prev.lng, lat, lng) >= 15) {
          renderAll(false);
        }
      },
      () => {},
      { enableHighAccuracy: false, maximumAge: 60000, timeout: 15000 }
    );
  } catch (_e) {}
}

function requestUserGPS(silent = false) {
  if (!navigator.geolocation) {
    if (!silent) {
      showToast("이 브라우저에서는 위치 기능을 지원하지 않아요.");
    }
    return;
  }

  // 이미 최근 파악된 GPS 좌표가 있으면 즉시 먼저 요정을 이동시켜 체감 지연 0초 제공
  if (state.userGpsCoord && state.userGpsCoord.lat) {
    state.anchorKey = "gps";
    state.anchorCoord = { ...state.userGpsCoord };
    renderAll(true);
  } else if (!silent) {
    setLoadingState(true, "내 위치 찾는 중…");
  }

  // 1차 시도: 빠른 응답을 위해 캐시 허용(maximumAge: 120초) + 넉넉한 타임아웃(10초)
  navigator.geolocation.getCurrentPosition(
    (pos) => {
      applyGpsPosition(pos, true, silent);
      startContinuousGpsWatch();
    },
    () => {
      // 2차 재시도: 고정밀(enableHighAccuracy: true)이 실내/Wi-Fi에서 타임아웃될 때 일반 네트워크/Wi-Fi 측위로 즉시 폴백
      navigator.geolocation.getCurrentPosition(
        (pos2) => {
          applyGpsPosition(pos2, true, silent);
          startContinuousGpsWatch();
        },
        (err2) => {
          setLoadingState(false);
          if (state.userGpsCoord && state.userGpsCoord.lat) {
            state.anchorKey = "gps";
            state.anchorCoord = { ...state.userGpsCoord };
            renderAll(true);
            return;
          }
          const fallback = CAMPUS_ANCHORS[state.campus][0];
          state.anchorKey = fallback.key;
          state.anchorCoord = {
            lat: fallback.lat,
            lng: fallback.lng,
            label: fallback.label,
          };
          if (!silent) {
            const msg =
              err2 && err2.code === 1
                ? "브라우저 주소창 왼쪽에서 위치 권한을 '허용'해 주시면 내 위치에 제발요가 나타나요!"
                : "실내 GPS 신호가 약해 현재 캠퍼스 정문 기준으로 제발요가 안내해 드려요.";
            showToast(msg);
          }
          renderAll(true);
        },
        { enableHighAccuracy: false, timeout: 12000, maximumAge: 600000 }
      );
    },
    { enableHighAccuracy: true, timeout: 7000, maximumAge: 120000 }
  );
}

// 20. 공유 링크 복사 및 인앱/A2HS 안내 시트
function showToast(msg) {
  const toastEl = document.getElementById("toastPopup");
  if (!toastEl) return;
  toastEl.textContent = msg;
  toastEl.classList.add("show");
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => {
    toastEl.classList.remove("show");
  }, 2400);
}

async function copyShareLink(placeId = null) {
  const targetUrl = getCanonicalShareUrl(placeId);
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(targetUrl);
    } else {
      throw new Error("clipboard fallback");
    }
  } catch {
    const tempInput = document.createElement("input");
    tempInput.value = targetUrl;
    document.body.appendChild(tempInput);
    tempInput.select();
    document.execCommand("copy");
    document.body.removeChild(tempInput);
  }
  showToast("카공맵 링크가 복사되었어요.");
}

function isInAppBrowser() {
  const ua = navigator.userAgent || "";
  return /Instagram|KAKAOTALK|everytime|NAVER|Line|FBAN|FBAV/i.test(ua);
}

function showA2HSPopup(forceInAppMode = false) {
  const modal = document.getElementById("a2hsModal");
  const titleEl = document.getElementById("a2hsTitle");
  const subtitleEl = document.getElementById("a2hsSubtitle");
  const bodyEl = document.getElementById("a2hsInstructionBody");
  if (!modal || !bodyEl) return;

  const inApp = forceInAppMode === true || isInAppBrowser();
  if (inApp) {
    if (titleEl) {
      titleEl.textContent = "외부 브라우저로 열면 더 편해요";
    }
    if (subtitleEl) {
      subtitleEl.textContent =
        "인스타그램·카카오톡 인앱 브라우저에서는 내 위치 탐색과 홈 화면 추가가 제한될 수 있어요.";
    }
    bodyEl.innerHTML = `
      <ol class="a2hs-steps">
        <li><span class="step-num">1</span><span>우측 상단 또는 하단의 <strong>메뉴(⋯)</strong> 버튼을 눌러주세요.</span></li>
        <li><span class="step-num">2</span><span><strong>다른 브라우저로 열기(Safari / Chrome)</strong>를 선택해 주세요.</span></li>
        <li><span class="step-num">3</span><span>브라우저 공유 메뉴에서 <strong>홈 화면에 추가</strong>를 누르면 바로가기가 만들어져요.</span></li>
      </ol>
    `;
  } else {
    const isIOS = /iPhone|iPad|iPod/i.test(navigator.userAgent || "");
    if (titleEl) {
      titleEl.textContent = "홈 화면에 카공맵 추가하기";
    }
    if (subtitleEl) {
      subtitleEl.textContent =
        "시험기간·공강 때마다 앱처럼 바로 열어 내 주변 카공 카페를 확인할 수 있어요.";
    }
    bodyEl.innerHTML = isIOS
      ? `
      <ol class="a2hs-steps">
        <li><span class="step-num">1</span><span>Safari 하단 바의 <strong>공유 버튼</strong>을 눌러주세요.</span></li>
        <li><span class="step-num">2</span><span>메뉴에서 <strong>홈 화면에 추가</strong>를 선택하면 완료돼요.</span></li>
      </ol>`
      : `
      <ol class="a2hs-steps">
        <li><span class="step-num">1</span><span>브라우저 우측 상단 <strong>메뉴(⋮)</strong> 버튼을 눌러주세요.</span></li>
        <li><span class="step-num">2</span><span><strong>홈 화면에 추가</strong> 또는 <strong>앱 설치</strong>를 선택하면 완료돼요.</span></li>
      </ol>`;
  }

  modal.classList.remove("hidden");
  trackEvent("a2hs_shown", { in_app: inApp });
}

window.showA2HSPopup = showA2HSPopup;

// 20-2. 3-3절: "정보가 달라요" 수정 제보 시트 열기 및 클립보드 복사 연동
let currentReportPlace = null;
let selectedReportType = "영업시간·휴무일이 달라요";

function openReportModal(place) {
  currentReportPlace = place;
  const modal = document.getElementById("reportModal");
  const titleEl = document.getElementById("reportModalTitle");
  const noteInput = document.getElementById("reportNoteInput");
  if (!modal) {
    if (REPORT_FORM_URL && REPORT_FORM_URL.trim()) {
      window.open(REPORT_FORM_URL.trim(), "_blank", "noopener,noreferrer");
    }
    return;
  }

  if (titleEl && place) {
    titleEl.textContent = `${place.name} · 정보가 달라요`;
  }
  if (noteInput) {
    noteInput.value = "";
  }
  modal.classList.remove("hidden");
}

function openSuggestCafeModal() {
  const modal = document.getElementById("suggestCafeModal");
  if (!modal) return;

  // 현재 선택된 캠퍼스로 기본 동기화
  modal.querySelectorAll("[data-suggest-campus]").forEach((btn) => {
    btn.classList.toggle("is-selected", btn.dataset.suggestCampus === state.campus);
  });

  const nameInput = document.getElementById("suggestNameInput");
  const locInput = document.getElementById("suggestLocationInput");
  const metaInput = document.getElementById("suggestMetaInput");
  const revInput = document.getElementById("suggestReviewInput");
  if (nameInput) nameInput.value = "";
  if (locInput) locInput.value = "";
  if (metaInput) metaInput.value = "";
  if (revInput) revInput.value = "";

  modal.classList.remove("hidden");
  trackEvent("open_suggest_cafe_modal", { campus: state.campus });
}

// 21. 전체 UI 통합 렌더링
function renderAll(recenterMap = false) {
  updateURLParams();
  const refDate = getEffectiveReferenceDate();
  const displayedPlaces = getSortedDisplayPlaces(refDate);

  renderControlsAndGreeting(displayedPlaces, refDate);
  updateMoodCardsInPlace(refDate);
  updateDetailChipsInPlace(refDate);
  renderAiPromptResultBox(refDate);
  renderPlaceList(displayedPlaces);
  renderMapView(displayedPlaces);

  if (currentFairyNavSession) {
    updateMapTurnByTurnHud();
  } else if (state.selectedPlaceId !== null) {
    openPlaceDetail(state.selectedPlaceId, false);
  }

  if (recenterMap && leafletMap) {
    setTimeout(() => {
      leafletMap.invalidateSize();
      const targetZoom =
        state.anchorKey === "gps"
          ? 16
          : state.radiusMeters === 300 || state.radiusMeters === 500
          ? 16
          : 15;
      leafletMap.setView([state.anchorCoord.lat, state.anchorCoord.lng], targetZoom);
      syncMapZoomClass();
    }, 50);
  }
}

// 22. 이벤트 바인딩
function bindEvents() {
  // 지도 보기 ↔ 카페 목록 보기 탭 및 플로팅 전환 버튼
  const btnTabMapView = document.getElementById("btnTabMapView");
  const btnTabListView = document.getElementById("btnTabListView");
  const btnFloatingToList = document.getElementById("btnFloatingToList");
  const btnListBackToMap = document.getElementById("btnListBackToMap");

  if (btnTabMapView) {
    btnTabMapView.addEventListener("click", () => {
      setMainViewMode("map", "top_tab");
    });
  }
  if (btnTabListView) {
    btnTabListView.addEventListener("click", () => {
      setMainViewMode("list", "top_tab");
    });
  }
  if (btnFloatingToList) {
    btnFloatingToList.addEventListener("click", () => {
      setMainViewMode("list", "map_floating_pill");
    });
  }
  if (btnListBackToMap) {
    btnListBackToMap.addEventListener("click", () => {
      setMainViewMode("map", "list_guide_btn");
    });
  }

  // 캠퍼스 세그먼트 전환
  document.querySelectorAll(".campus-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const nextCampus = btn.dataset.campus;
      if (!nextCampus || nextCampus === state.campus) return;
      state.campus = nextCampus;
      const defaultAnchor = CAMPUS_ANCHORS[state.campus][0];
      state.anchorKey = defaultAnchor.key;
      state.anchorCoord = {
        lat: defaultAnchor.lat,
        lng: defaultAnchor.lng,
        label: defaultAnchor.label,
      };
      closePlaceDetail();
      trackEvent("campus_change", { campus: state.campus });
      renderAll(true);
    });
  });

  // 상단 메뉴 버튼 & 드롭다운
  const btnHeaderMenu = document.getElementById("btnHeaderMenu");
  const menuDropdown = document.getElementById("headerMenuDropdown");
  if (btnHeaderMenu && menuDropdown) {
    btnHeaderMenu.addEventListener("click", (e) => {
      e.stopPropagation();
      const isHidden = menuDropdown.classList.toggle("hidden");
      btnHeaderMenu.setAttribute("aria-expanded", !isHidden ? "true" : "false");
    });
    document.addEventListener("click", () => {
      menuDropdown.classList.add("hidden");
      btnHeaderMenu.setAttribute("aria-expanded", "false");
    });
  }

  // 메뉴 항목: 공유 / 홈 화면 추가 / Google AI Pro 혜택
  const btnMenuShare = document.getElementById("btnMenuShare");
  if (btnMenuShare) {
    btnMenuShare.addEventListener("click", () => copyShareLink());
  }

  const btnMenuA2HS = document.getElementById("btnMenuA2HS");
  if (btnMenuA2HS) {
    btnMenuA2HS.addEventListener("click", () => showA2HSPopup(false));
  }

  const offerModal = document.getElementById("geminiOfferModal");
  const openOfferModal = (source) => {
    if (!offerModal) return;
    offerModal.classList.remove("hidden");
    trackEvent("cta_click", {
      campus: state.campus,
      utm_content: `${state.campus}_kagong`,
      source,
    });
  };

  const btnMenuOffer = document.getElementById("btnMenuOffer");
  if (btnMenuOffer) {
    btnMenuOffer.addEventListener("click", () => openOfferModal("header_menu"));
  }

  const btnRefreshLiveInfo = document.getElementById("btnRefreshLiveInfo");
  if (btnRefreshLiveInfo) {
    btnRefreshLiveInfo.addEventListener("click", () => {
      refreshAllLiveBusinessInfo();
    });
  }

  const btnMenuRefreshLive = document.getElementById("btnMenuRefreshLive");
  if (btnMenuRefreshLive) {
    btnMenuRefreshLive.addEventListener("click", () => {
      const headerDropdown = document.getElementById("headerMenuDropdown");
      if (headerDropdown) headerDropdown.classList.add("hidden");
      refreshAllLiveBusinessInfo();
    });
  }

  const btnOpenOfferFromList = document.getElementById("btnOpenOfferFromList");
  if (btnOpenOfferFromList) {
    btnOpenOfferFromList.addEventListener("click", () =>
      openOfferModal("sheet_subtle_banner")
    );
  }

  const btnQuickOfferPill = document.getElementById("btnQuickOfferPill");
  if (btnQuickOfferPill) {
    btnQuickOfferPill.addEventListener("click", () =>
      openOfferModal("filter_bar_pill")
    );
  }

  const btnCloseOfferSheet = document.getElementById("btnCloseOfferSheet");
  if (btnCloseOfferSheet && offerModal) {
    btnCloseOfferSheet.addEventListener("click", () =>
      offerModal.classList.add("hidden")
    );
    offerModal.addEventListener("click", (e) => {
      if (e.target === offerModal) offerModal.classList.add("hidden");
    });
  }

  // 요정 인사말 닫기 및 요정 클릭 인터랙션 (헤더 로고 요정 + 바텀시트 삼총사 요정)
  const btnDismissGreeting = document.getElementById("btnDismissGreeting");
  if (btnDismissGreeting) {
    btnDismissGreeting.addEventListener("click", () => {
      state.greetingDismissed = true;
      const bar = document.getElementById("fairyGreetingBar");
      if (bar) bar.classList.add("hidden");
    });
  }

  const brandFairyTrigger = document.getElementById("brandFairyTrigger");
  const headerFairyImg = document.getElementById("headerFairyImg");
  if (brandFairyTrigger) {
    brandFairyTrigger.addEventListener("click", () => {
      const msg = cycleFairyCheerMessage(headerFairyImg || brandFairyTrigger);
      const greetingImg = document.getElementById("greetingFairyImg");
      if (greetingImg) triggerFairySparkleAndHop(greetingImg);
      showToast(msg);
    });
  }

  const btnFairyCheer = document.getElementById("btnFairyCheer");
  const greetingTextTrigger = document.getElementById("greetingTextTrigger");
  const onGreetingFairyClick = () => {
    state._customGreetingLocked = true;
    const greetingImg = document.getElementById("greetingFairyImg");
    cycleFairyCheerMessage(greetingImg);
  };
  if (btnFairyCheer) {
    btnFairyCheer.addEventListener("click", onGreetingFairyClick);
  }
  if (greetingTextTrigger) {
    greetingTextTrigger.addEventListener("click", onGreetingFairyClick);
  }

  // 요정 인사 바 안의 1탭 빠른 시간대 선택 알약 (지금 / 내일 아침 9시 / 낮 2시 / 밤 10시 / 닫은 곳도 보기)
  const quickTimeRow = document.getElementById("fairyQuickTimeRow");
  if (quickTimeRow) {
    quickTimeRow.addEventListener("click", (e) => {
      const pill = e.target.closest("[data-quick-time]");
      if (!pill) return;
      const mode = pill.dataset.quickTime;
      const greetingImg = document.getElementById("greetingFairyImg");
      triggerFairySparkleAndHop(greetingImg);
      state._customGreetingLocked = false;

      if (mode === "all_places") {
        state.openNowOnly = !state.openNowOnly;
        trackEvent("toggle_open_now", {
          open_now_only: state.openNowOnly,
          source: "fairy_quick_pill",
        });
        showToast(
          state.openNowOnly
            ? "영업 중인 카페만 모아서 보여드려요."
            : "영업 종료된 카페도 모두 함께 보여드려요!"
        );
      } else {
        state.visitTimeMode = mode;
        state.openNowOnly = true;
        const customTimeInput = document.getElementById("customTimeInput");
        if (customTimeInput) customTimeInput.classList.add("hidden");
        trackEvent("change_visit_time", {
          mode,
          source: "fairy_quick_pill",
        });
        const labelMap = {
          now: "지금 열려 있는 카페 기준으로 보여드려요!",
          morning09: "내일 아침 9시에 문 여는 카페들을 찾았어요!",
          afternoon14: "오후 2시에 영업 중인 카페들을 찾았어요!",
          tonight22: "밤 10시에도 열려 있는 카페들을 찾았어요!",
        };
        if (labelMap[mode]) showToast(labelMap[mode]);
      }

      renderAll(false);
    });
  }

  // 4-1절: 통합 검색 모달 내부의 카공 카드 클릭 (다시 누르면 해제, 세부 조건과 함께 조합 가능)
  const moodTrack = document.getElementById("moodCardsTrack");
  if (moodTrack) {
    moodTrack.addEventListener("click", (e) => {
      const card = e.target.closest(".mood-card");
      if (!card) return;

      const moodId = card.dataset.moodId;
      const count = Number(card.dataset.currentCount || "0");

      if (state.selectedMood === moodId) {
        state.selectedMood = null;
        trackEvent("select_mood", { mood: "none" });
        renderAll(false);
        return;
      }

      if (count === 0) {
        showToast("아직 등록된 곳이 없어요");
        trackEvent("select_mood", { mood: moodId, empty: true });
        return;
      }

      state.selectedMood = moodId;
      closePlaceDetail();
      trackEvent("select_mood", { mood: moodId, count });
      renderAll(false);
    });
  }

  // 4-2절: 통합 검색창(#btnOpenDetailFilter) 클릭 시 통합 검색·필터 모달(#detailFilterModal) 열기
  const btnInlineDetailReset = document.getElementById("btnInlineDetailReset");
  const detailModal = document.getElementById("detailFilterModal");
  const btnOpenDetail = document.getElementById("btnOpenDetailFilter");
  const btnCloseDetail = document.getElementById("btnCloseDetailFilter");
  const btnApplyDetail = document.getElementById("btnApplyDetailFilter");
  const btnResetDetail = document.getElementById("btnResetDetailFilters");
  const detailGrid = document.getElementById("detailChipGrid");

  if (btnOpenDetail && detailModal) {
    btnOpenDetail.addEventListener("click", () => {
      detailModal.classList.remove("hidden");
      const inputEl = document.getElementById("aiPromptInput");
      if (inputEl) {
        inputEl.value = state.aiPromptQuery || "";
      }
      trackEvent("open_detail_filters", {
        active_count: state.selectedDetails.size,
      });
      renderAll(false);
    });
  }

  const handleDetailChipClick = (e) => {
    const chip = e.target.closest(".detail-cond-chip");
    if (!chip) return;
    const key = chip.dataset.condKey;
    const remainCount = Number(chip.dataset.remainCount || "0");

    if (state.selectedDetails.has(key)) {
      state.selectedDetails.delete(key);
    } else {
      if (remainCount === 0) {
        showToast("선택 시 조건에 맞는 카페가 0곳이 돼요.");
        return;
      }
      state.selectedDetails.add(key);
    }

    trackEvent("filter_click", {
      tag: key,
      active_tags: Array.from(state.selectedDetails).join(","),
      active_count: state.selectedDetails.size,
    });
    renderAll(false);
  };

  if (detailGrid) {
    detailGrid.addEventListener("click", handleDetailChipClick);
  }

  const resetAllUnifiedSearch = () => {
    state.selectedMood = null;
    state.selectedDetails.clear();
    state.aiPromptQuery = "";
    const inputEl = document.getElementById("aiPromptInput");
    if (inputEl) inputEl.value = "";
    trackEvent("filter_click", { action: "reset_unified_search" });
    renderAll(false);
  };

  if (btnInlineDetailReset) {
    btnInlineDetailReset.addEventListener("click", (e) => {
      e.stopPropagation();
      resetAllUnifiedSearch();
      showToast("검색 및 필터 조건이 초기화되었어요.");
    });
  }

  if (btnCloseDetail && detailModal) {
    btnCloseDetail.addEventListener("click", () =>
      detailModal.classList.add("hidden")
    );
    detailModal.addEventListener("click", (e) => {
      if (e.target === detailModal) detailModal.classList.add("hidden");
    });
  }

  // 통합 검색 모달 하단 "추천받기" 버튼 1개: 입력된 프롬프트 또는 선택한 카공 카드·세부 조건으로 즉시 추천 실행!
  if (btnApplyDetail && detailModal) {
    btnApplyDetail.addEventListener("click", () => {
      const inputEl = document.getElementById("aiPromptInput");
      const val = inputEl ? inputEl.value.trim() : "";
      if (val) {
        applyAiPromptRecommendation(val, false);
      } else {
        state.aiPromptQuery = "";
        detailModal.classList.add("hidden");
        renderAll(false);
        setSheetSnapMode("half");
        if (state.selectedMood || state.selectedDetails.size > 0) {
          showToast("🧚 선택한 조건에 맞는 추천 카페를 찾았어요!");
        }
      }
    });
  }

  if (btnResetDetail) {
    btnResetDetail.addEventListener("click", () => {
      resetAllUnifiedSearch();
    });
  }

  // Gemini API 키 설정 토글 & 저장/해제 이벤트
  const btnToggleGeminiKeyBox = document.getElementById("btnToggleGeminiKeyBox");
  const btnMenuGeminiKey = document.getElementById("btnMenuGeminiKey");
  const geminiApiKeyBox = document.getElementById("geminiApiKeyBox");
  const geminiApiKeyInput = document.getElementById("geminiApiKeyInput");
  const btnSaveGeminiKey = document.getElementById("btnSaveGeminiKey");
  const btnClearGeminiKey = document.getElementById("btnClearGeminiKey");

  syncGeminiKeyUiState();

  if (btnToggleGeminiKeyBox && geminiApiKeyBox) {
    btnToggleGeminiKeyBox.addEventListener("click", () => {
      geminiApiKeyBox.classList.toggle("hidden");
      syncGeminiKeyUiState();
    });
  }

  if (btnMenuGeminiKey && detailModal && geminiApiKeyBox) {
    btnMenuGeminiKey.addEventListener("click", () => {
      const headerDropdown = document.getElementById("headerMenuDropdown");
      if (headerDropdown) headerDropdown.classList.add("hidden");
      detailModal.classList.remove("hidden");
      geminiApiKeyBox.classList.remove("hidden");
      syncGeminiKeyUiState();
      if (geminiApiKeyInput) geminiApiKeyInput.focus();
    });
  }

  if (btnSaveGeminiKey && geminiApiKeyInput) {
    btnSaveGeminiKey.addEventListener("click", () => {
      const keyVal = geminiApiKeyInput.value.trim();
      if (!keyVal) {
        showToast("Gemini API 키(AIza...)를 입력해 주세요!");
        return;
      }
      try {
        localStorage.setItem(GEMINI_KEY_STORAGE, keyVal);
      } catch (_e) {}
      geminiReplyCache.clear();
      syncGeminiKeyUiState();
      if (geminiApiKeyBox) geminiApiKeyBox.classList.add("hidden");
      renderAiPromptResultBox(getEffectiveReferenceDate());
      showToast("⚡ Gemini 2.5 Flash API 키가 연동되었어요!");
    });
  }

  if (btnClearGeminiKey && geminiApiKeyInput) {
    btnClearGeminiKey.addEventListener("click", () => {
      geminiApiKeyInput.value = "";
      try {
        localStorage.removeItem(GEMINI_KEY_STORAGE);
      } catch (_e) {}
      geminiReplyCache.clear();
      syncGeminiKeyUiState();
      renderAiPromptResultBox(getEffectiveReferenceDate());
      showToast("기본 제발요 대화형 브리핑 모드로 전환되었어요.");
    });
  }

  // 기준점 드롭다운 변경
  const selectAnchor = document.getElementById("selectAnchor");
  if (selectAnchor) {
    selectAnchor.addEventListener("change", () => {
      const val = selectAnchor.value;
      if (val === "gps") {
        requestUserGPS();
      } else {
        const found = CAMPUS_ANCHORS[state.campus].find((a) => a.key === val);
        if (found) {
          state.anchorKey = found.key;
          state.anchorCoord = {
            lat: found.lat,
            lng: found.lng,
            label: found.label,
          };
          closePlaceDetail();
          renderAll(true);
        }
      }
    });
  }

  // 반경 드롭다운 변경 (300m / 500m / 1km / 전체)
  const selectRadius = document.getElementById("selectRadius");
  if (selectRadius) {
    selectRadius.addEventListener("change", () => {
      state.radiusMeters = Number(selectRadius.value);
      closePlaceDetail();
      renderAll(true);
    });
  }

  // 언제 갈 거예요? 시간 선택 변경
  const selectVisitTime = document.getElementById("selectVisitTime");
  const customTimeInput = document.getElementById("customTimeInput");
  if (selectVisitTime) {
    selectVisitTime.addEventListener("change", () => {
      state.visitTimeMode = selectVisitTime.value;
      if (customTimeInput) {
        customTimeInput.classList.toggle(
          "hidden",
          state.visitTimeMode !== "custom"
        );
      }
      trackEvent("change_visit_time", {
        mode: state.visitTimeMode,
        custom_time: state.customTimeValue,
      });
      renderAll(false);
    });
  }

  if (customTimeInput) {
    customTimeInput.addEventListener("change", () => {
      state.customTimeValue = customTimeInput.value || "23:00";
      trackEvent("change_visit_time", {
        mode: "custom",
        custom_time: state.customTimeValue,
      });
      renderAll(false);
    });
  }

  // 지금 영업 중만 토글
  const btnToggleOpenNow = document.getElementById("btnToggleOpenNow");
  if (btnToggleOpenNow) {
    btnToggleOpenNow.addEventListener("click", () => {
      state.openNowOnly = !state.openNowOnly;
      trackEvent("toggle_open_now", { open_now_only: state.openNowOnly });
      renderAll(false);
    });
  }

  // 목록 카드 클릭 -> 상세 시트 오픈
  const listContainer = document.getElementById("placeListContainer");
  if (listContainer) {
    listContainer.addEventListener("click", (e) => {
      const card = e.target.closest(".place-card");
      if (!card) return;
      const id = Number(card.dataset.placeId);
      trackEvent("place_click", {
        place_id: id,
        source: "sheet_list_card",
      });
      openPlaceDetail(id, true);
    });

    listContainer.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        const card = e.target.closest(".place-card");
        if (!card) return;
        e.preventDefault();
        openPlaceDetail(Number(card.dataset.placeId), true);
      }
    });
  }

  // 지도 우측 하단 커스텀 버튼 (내 위치 / 확대 / 축소)
  const btnMyLoc = document.getElementById("btnMapMyLocation");
  if (btnMyLoc) {
    btnMyLoc.addEventListener("click", () => requestUserGPS());
  }
  const btnZoomIn = document.getElementById("btnMapZoomIn");
  if (btnZoomIn) {
    btnZoomIn.addEventListener("click", () => {
      if (leafletMap) leafletMap.zoomIn();
    });
  }
  const btnZoomOut = document.getElementById("btnMapZoomOut");
  if (btnZoomOut) {
    btnZoomOut.addEventListener("click", () => {
      if (leafletMap) leafletMap.zoomOut();
    });
  }

  // A2HS 모달 닫기 및 복사
  const a2hsModal = document.getElementById("a2hsModal");
  const btnCloseA2HS = document.getElementById("btnCloseA2HS");
  const btnA2HSCopyLink = document.getElementById("btnA2HSCopyLink");
  if (btnCloseA2HS && a2hsModal) {
    btnCloseA2HS.addEventListener("click", () =>
      a2hsModal.classList.add("hidden")
    );
    a2hsModal.addEventListener("click", (e) => {
      if (e.target === a2hsModal) a2hsModal.classList.add("hidden");
    });
  }
  if (btnA2HSCopyLink) {
    btnA2HSCopyLink.addEventListener("click", () => copyShareLink());
  }

  // 3-3절: 정보가 달라요 (제보 모달) 이벤트 바인딩
  const reportModal = document.getElementById("reportModal");
  const btnCloseReportModal = document.getElementById("btnCloseReportModal");
  const reportTypeGrid = document.getElementById("reportTypeGrid");
  const btnSubmitReportSheet = document.getElementById("btnSubmitReportSheet");
  const reportNoteInput = document.getElementById("reportNoteInput");

  if (btnCloseReportModal && reportModal) {
    btnCloseReportModal.addEventListener("click", () =>
      reportModal.classList.add("hidden")
    );
    reportModal.addEventListener("click", (e) => {
      if (e.target === reportModal) reportModal.classList.add("hidden");
    });
  }

  if (reportTypeGrid) {
    reportTypeGrid.addEventListener("click", (e) => {
      const chip = e.target.closest("[data-report-type]");
      if (!chip) return;
      selectedReportType = chip.dataset.reportType;
      reportTypeGrid.querySelectorAll("[data-report-type]").forEach((el) => {
        el.classList.toggle("is-selected", el === chip);
      });
    });
  }

  if (btnSubmitReportSheet) {
    btnSubmitReportSheet.addEventListener("click", async () => {
      const placeName = currentReportPlace ? currentReportPlace.name : "카페";
      const campusLabel =
        currentReportPlace && currentReportPlace.campus === "global"
          ? "국제캠"
          : "서울캠";
      const noteText = reportNoteInput ? reportNoteInput.value.trim() : "";
      const summaryLine = `[카공맵 정보 수정 제보] (${campusLabel}) ${placeName} - ${selectedReportType}${
        noteText ? ` : ${noteText}` : ""
      }`;

      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          await navigator.clipboard.writeText(summaryLine);
        }
      } catch {
        // clipboard fallback 생략 가능
      }

      showToast("제보 내용이 복사되었어요. 시트 또는 폼에 붙여넣어 주세요!");
      if (reportModal) reportModal.classList.add("hidden");

      if (REPORT_FORM_URL && REPORT_FORM_URL.trim()) {
        window.open(REPORT_FORM_URL.trim(), "_blank", "noopener,noreferrer");
      }
    });
  }

  // 20-3. 새 카공 카페 건의하기 & 후기 남기기 모달 바인딩
  const suggestModal = document.getElementById("suggestCafeModal");
  const btnOpenSuggestCafe = document.getElementById("btnOpenSuggestCafe");
  const btnMenuSuggestCafe = document.getElementById("btnMenuSuggestCafe");
  const btnCloseSuggestModal = document.getElementById("btnCloseSuggestModal");
  const suggestTagGrid = document.getElementById("suggestTagGrid");
  const btnSubmitSuggestCafe = document.getElementById("btnSubmitSuggestCafe");

  if (btnOpenSuggestCafe) {
    btnOpenSuggestCafe.addEventListener("click", () => openSuggestCafeModal());
  }
  if (btnMenuSuggestCafe) {
    btnMenuSuggestCafe.addEventListener("click", () => openSuggestCafeModal());
  }
  if (btnCloseSuggestModal && suggestModal) {
    btnCloseSuggestModal.addEventListener("click", () =>
      suggestModal.classList.add("hidden")
    );
    suggestModal.addEventListener("click", (e) => {
      if (e.target === suggestModal) suggestModal.classList.add("hidden");
    });
  }

  if (suggestModal) {
    suggestModal.querySelectorAll("[data-suggest-campus]").forEach((btn) => {
      btn.addEventListener("click", () => {
        suggestModal.querySelectorAll("[data-suggest-campus]").forEach((el) => {
          el.classList.toggle("is-selected", el === btn);
        });
      });
    });
  }

  if (suggestTagGrid) {
    suggestTagGrid.addEventListener("click", (e) => {
      const chip = e.target.closest("[data-suggest-tag]");
      if (!chip) return;
      chip.classList.toggle("is-selected");
    });
  }

  if (btnSubmitSuggestCafe && suggestModal) {
    btnSubmitSuggestCafe.addEventListener("click", async () => {
      const nameInput = document.getElementById("suggestNameInput");
      const locInput = document.getElementById("suggestLocationInput");
      const metaInput = document.getElementById("suggestMetaInput");
      const revInput = document.getElementById("suggestReviewInput");

      const cafeName = nameInput ? nameInput.value.trim() : "";
      if (!cafeName) {
        showToast("건의할 카페 이름을 입력해 주세요!");
        if (nameInput) nameInput.focus();
        return;
      }

      const activeCampusBtn = suggestModal.querySelector(
        "[data-suggest-campus].is-selected"
      );
      const targetCampus = activeCampusBtn
        ? activeCampusBtn.dataset.suggestCampus
        : state.campus;

      const selectedTags = [];
      if (suggestTagGrid) {
        suggestTagGrid
          .querySelectorAll("[data-suggest-tag].is-selected")
          .forEach((el) => {
            selectedTags.push(el.dataset.suggestTag);
          });
      }
      if (selectedTags.length === 0) {
        selectedTags.push("콘센트많음", "1인석");
      }

      const locHint = locInput ? locInput.value.trim() : "";
      const metaHint = metaInput ? metaInput.value.trim() : "";
      const revText = revInput ? revInput.value.trim() : "";

      const baseAnchor = CAMPUS_ANCHORS[targetCampus][0];
      const seedOffset = ((Date.now() % 7) - 3) * 0.00045;
      const newId = 1000 + getUserSuggestedCafes().length + 1;

      const newCafe = {
        id: newId,
        campus: targetCampus,
        name: cafeName,
        lat: Number((baseAnchor.lat + 0.0009 + seedOffset).toFixed(6)),
        lng: Number((baseAnchor.lng + 0.0008 - seedOffset).toFixed(6)),
        tags: selectedTags,
        days: "월~일",
        hours: "09:00~22:00",
        outlets: metaHint || "경희인 건의로 등록된 카공 추천 좌석",
        summary:
          revText ||
          (locHint
            ? `${locHint} 인근 · 경희인이 직접 추천한 카공 스팟`
            : "경희인이 직접 건의해 추가된 카공 카페"),
        link: `https://map.naver.com/p/search/${encodeURIComponent(cafeName)}`,
        status: "운영",
        verified_at: new Date().toISOString().slice(0, 10),
        hours_detail: "월-일 09:00-22:00",
        break_time: "",
        last_order: "",
        closed_days: "",
        note: locHint ? `위치 힌트: ${locHint}` : "경희인 건의 카페",
        image_url: "",
      };

      saveUserSuggestedCafe(newCafe);
      state.places.push(newCafe);

      if (revText) {
        savePlaceReview(newId, "경희인 추천", revText);
      }

      const campusLabel = targetCampus === "global" ? "국제캠" : "서울캠";
      const clipText = `[카공맵 새 카페 건의] (${campusLabel}) ${cafeName} | 위치: ${
        locHint || "-"
      } | 특징: ${selectedTags.join(", ")} | 콘센트·시간: ${
        metaHint || "-"
      } | 후기: ${revText || "-"}`;

      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          await navigator.clipboard.writeText(clipText);
        }
      } catch (_e) {}

      suggestModal.classList.add("hidden");
      if (state.campus !== targetCampus) {
        state.campus = targetCampus;
        const defaultAnchor = CAMPUS_ANCHORS[state.campus][0];
        state.anchorKey = defaultAnchor.key;
        state.anchorCoord = {
          lat: defaultAnchor.lat,
          lng: defaultAnchor.lng,
          label: defaultAnchor.label,
        };
      }
      state.openNowOnly = false;
      renderAll(true);
      openPlaceDetail(newId, true);
      showToast(`✨ '${cafeName}' 카페가 지도에 바로 추가되고 건의 내용이 복사되었어요!`);
    });
  }

  // 20-4. ✨ AI 프롬프트 카페 추천 입력 폼 & 지우기 버튼 바인딩
  const aiPromptForm = document.getElementById("aiPromptForm");
  const aiPromptInput = document.getElementById("aiPromptInput");
  const btnClearAiPrompt = document.getElementById("btnClearAiPrompt");

  if (aiPromptForm && aiPromptInput) {
    aiPromptForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const val = aiPromptInput.value.trim();
      if (!val) {
        showToast("원하는 카공 조건을 문장으로 입력해 보세요! (예: 조용하고 콘센트 많은 곳)");
        aiPromptInput.focus();
        return;
      }
      applyAiPromptRecommendation(val, false);
    });

    aiPromptInput.addEventListener("input", () => {
      if (btnClearAiPrompt) {
        btnClearAiPrompt.classList.toggle("hidden", !aiPromptInput.value.trim());
      }
    });
  }

  if (btnClearAiPrompt && aiPromptInput) {
    btnClearAiPrompt.addEventListener("click", () => {
      aiPromptInput.value = "";
      applyAiPromptRecommendation("", false);
    });
  }
}

// 23. 앱 초기화 및 1분 주기 영업시간 상태 갱신
async function initApp() {
  initGA4();
  syncStateFromURL();
  mountMoodCardsOnce();
  mountDetailChipsOnce();
  initBottomSheetDrag();
  initHorizontalSwipeNavigation();
  bindEvents();

  setLoadingState(true, "자리 알아보는 중…");
  try {
    state.places = await loadPlacesData();
  } catch (err) {
    console.error("데이터 로드 오류:", err);
  } finally {
    setLoadingState(false);
  }

  // URL에 ?q=... 또는 ?prompt=... 추천 프롬프트가 담겨 공유된 경우 자동 추천 실행!
  if (state.aiPromptQuery) {
    applyAiPromptRecommendation(state.aiPromptQuery, true);
  } else {
    renderAll(true);
  }

  // URL에 ?anchor=gps가 지정되었거나 브라우저에 이미 위치 권한이 허용('granted')된 경우 자동으로 내 위치를 파악해 요정을 내 위치에 띄움
  if (state.anchorKey === "gps") {
    requestUserGPS(false);
  } else if (navigator.permissions && navigator.permissions.query) {
    try {
      navigator.permissions
        .query({ name: "geolocation" })
        .then((perm) => {
          if (perm.state === "granted") {
            requestUserGPS(true);
          }
        })
        .catch(() => {});
    } catch (_e) {}
  }

  const params = new URLSearchParams(window.location.search);
  const initialPlaceId = Number(params.get("place"));
  if (initialPlaceId) {
    openPlaceDetail(initialPlaceId, true);
  }

  trackEvent("page_view", {
    campus: state.campus,
    mood: state.selectedMood || "none",
  });

  // 3-2절: 상태는 1분마다 다시 계산 (페이지를 켜둔 채 시간이 지나도 정확히 반영)
  if (refreshTimerId) clearInterval(refreshTimerId);
  refreshTimerId = setInterval(() => {
    renderAll(false);
  }, 60000);
}

document.addEventListener("DOMContentLoaded", initApp);
